UPDATE kb_asset SET sha256 = 'bfca753fb43ca667f86615eccc31a5fffa0f3e282e4fc0c20cbef8a820efab64', w = 2188, h = 400 WHERE path = '/kb-assets/theory/p28_r1_20219c9dea9c5375.png';

