-- Step 4: 乐观锁升级所有 P0 精修节点修订版本
-- Node 54 (A1-1.4.2) rev 5 -> 6
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 5;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 54 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 54: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (54, 6, $p0b_54$[{"t": "list", "id": "a1-1-4-2-b1", "imp": "core", "items": ["1、==键盘（字符与命令输入设备）==", "（1）^^向计算机输入字母、数字、符号、命令等信息^^", "（2）布局：功能键（ESC、F1~F12）、打字键盘（字母键、数字键、符号、修饰键（Ctrl、Shift、Alt 等））、光标控制键、小键盘（数字、数学运算符号等）、其他键（Windows 控制键、多媒体播放控制键等）", "（3）==键盘是计算机必不可少的输入设备==", "（4）==为了方便盲打，键盘上有两个定位，分别是“F”键和“J”键==", "（5）键盘有机械式（早期使用）和电容式（目前主流）。", "（6）常用接口：==USB(2.0、3.0)、PS/2（紫色接口）、无线接口（红外或者无线电波，需接收器插入USB接口）==。"], "title": "", "ordered": false}, {"h": 586, "t": "img", "w": 2220, "id": "a1-1-4-2-b2", "imp": "normal", "src": "/kb-assets/theory/p17_r1_3d48b69c58426c38.png", "title": ""}, {"t": "list", "id": "a1-1-4-2-b3", "imp": "core", "items": ["（7）^^电容式键盘特点^^：==无磨损和接触不良问题，耐久性、灵敏度和稳定性都比较好，击键声音小，手感较好，寿命较长。==", "2、==鼠标（命令输入设备）==", "（1）^^作用：控制屏幕上的鼠标箭头准确地定位在指定的位置处，然后通过按键（左键或右键）发出命令，完成各种操作。^^", "（2）==鼠标不是计算机必备输入设备，是常用输入设备。==", "（3）鼠标分类：机械式鼠标（过去使用）和光电式鼠标（目前主流）。", "（4）^^光电式鼠标通过激光或红外线识别鼠标器移动的方向和距离^^", "（5）^^光电鼠标使用微型镜头拍摄其下方的图像，由DSP（数字信号处理）分析判断鼠标器的移动方向和距离。^^", "（6）^^鼠标的分辨率是指鼠标每移动1 英寸光标在屏幕上通过的像素数目^^。使用dip(dot per inch)表示。", "（7）^^Windows 下常鼠标操作及功能^^：", "①、单击左键：选择对象（Ctrl+左单：选择多个不连继的；Shift+左单：选择多个连续），或选择执行某个菜单", "②、双击左键：打开文件/文件夹，或运行应用程序", "③、左键拖放：移动对象/复制对象（Ctrl+左键拖）/创建对象快捷方式（Alt+左键拖）等", "④、单击右键：弹出所指对象的快捷菜单", "⑤、向前/向后转动滚轮：显示窗口中前面/后面的内容（滚屏）", "（8）Windows 下常见鼠标状态："], "title": "", "ordered": false}, {"h": 506, "t": "img", "w": 1137, "id": "a1-1-4-2-b4", "imp": "normal", "src": "/kb-assets/theory/p18_r0_b6f8ee1670049bd1.png", "title": ""}, {"t": "list", "id": "a1-1-4-2-b5", "imp": "core", "items": ["(9)常用鼠标接口：RS-232(已不使用)、==PS/2（绿色，很少使用）、USB（主流）、无线鼠标（需要接收器）=="], "title": "", "ordered": false}, {"h": 340, "t": "img", "w": 1337, "id": "a1-1-4-2-b6", "imp": "normal", "src": "/kb-assets/theory/p18_r1_daf8174c7cdbf997.png", "title": ""}, {"t": "list", "id": "a1-1-4-2-b7", "imp": "core", "items": ["3、^^笔输入设备（手写板）^^", "（1）^^作用：兼容有键盘、鼠标和写字笔的功能（可替代键盘、鼠标输入字符、命令和作图），输入汉字需要运行“手写汉字识别软件”。^^", "（2）手写板分类：电阻式、电容式、电磁感应式", "（3）电磁感应笔：电磁感应笔发出电磁波，基板接受到电磁波后计算出笔的位置信息，然后传送给主机，主机立刻在屏幕上显示出笔的运动轨迹。笔尖相当于鼠标左键、按钮1 相当于鼠标右键、按钮2 相当于鼠标滚轮。", "（4）^^手写板接口：串行口、USB^^。", "（5）触摸屏（现在使用的）是在液晶面板上覆盖一层压力板，它对压力很敏感，当手指或笔尖施压其上时会有电流产生以确定压力源的位置，并对其进行跟踪，然后通过软件识别出用户所输入的信息。", "4、==扫描仪（图像输入设备）==", "==（1）扫描仪是将原稿（图片、照片、底片、书稿）输入计算机的一种输入设备==", "==（2）扫描仪输入到计算机中的是原稿的“图象”(bitmap，格式为：TIF),不是图形==", "==（3）工作原理（平板式）：进行光电转换（CCD 电荷耦合器件）,  产生电流并输出==", "==（4）常见扫描仪类型：平板式、滚筒式和胶片专用、手持式扫描仪==", "==（5）扫描仪主要性能指标：==", "==①、光学分辨率（dpi）：反映图像大小，dpi 越高清晰。例如：1200×2400 dpi==", "==②、==@@色彩位数（色彩深度）：反映色彩逼真度，色彩位数越多，图像越真实。例如：32 bit@@", "==③、扫描幅面：指被扫描的原稿的尺寸（最大）；例如：A3、A4 等==", "==④、与主机的接口类型：SCSI， USB，IEEE 1394 接口。==", "5、^^数码相机（图像输入设备）^^", "（1）功能：获取现实世界中景物的数字图像", "（2）^^成像芯片：CCD（电荷耦合器）或CMOS（互补金属氧化物半导体）^^", "（3）与传统相机的镜头、快门等设备基本相同", "（4）^^数码相机^^==默认使用JPG（JPEG 的简称）格式==。但有些专业摄影师会使用高级相机拍RAW 格式，是一种无损压缩图像格式。", "（5）^^性能指标：分辨率（dpi）、存储容量（存储容量越大，并不一定存储图像越多，还要看单个图像的分辨率）。^^", "（6）^^接口：USB、IEEE 1394 接口。^^", "6、^^摄像头（视频输入设备）^^", "（1）^^是一种视频输入设备，获取现实世界中景物的连续图像数字化输送至计算机中进行处理。^^", "（2）分类：数字摄像头和模拟摄像头", "（3）^^主要组成部件 ：镜头、CCD/CMOS、电源^^", "（4）^^性能指标：分辨率（dpi）、色域（RGB24、YUV）、图像压缩方式（静态JEPG）、彩色深度^^", "（5）^^接口：RS232、USB、IEEE 1394 接口。^^", "7、^^传感器（输入设备）^^", "（1）^^传感器是一种检测装置，能将感到的被检测的信息，并将其换成电信号供计算机处理（测量、转换、存储、显示或传输）。^^", "（2）^^触摸屏、摄像头、微型话筒等设备的核心都是传感器^^", "8、==在选定区选定行、段与全文==：^^在文档左侧的选定区^^：==单击鼠标左键选择一行==；双击鼠标左键选择一段；三击鼠标左键选择整个文档。", "9、==用鼠标调整行高与列宽==：==将鼠标移到行（或列）的边框上==，光标变为双向箭头时按住左键拖动，可调整行高（或列宽）；也可右击，在弹出的快捷菜单中选择“行高”或“列宽”。", "10、==功能键F1～F12的作用由前台程序决定==：==键盘上的12个功能键（F1～F12）的具体功能==，由正在前台执行的程序决定。", "11、==平板式扫描仪工作原理==：==光源发出的光照射放在玻璃板上的被扫描原稿==，原稿的反射光经反射镜反射后由镜头聚焦到 CCD 上，CCD（电荷耦合器件）进行光电转换，产生电流并输出；扫描臂沿扫描方向移动，逐行完成整幅原稿的扫描。", "12、==计算机中数据单位与字长==", "^^位（bit，比特）^^：==表示信息的最小单位==，1 bit 简写为 1b（小写字母 b）。", "^^字节（Byte）^^：==最常用的信息基本单位==，1 Byte 简写为 1B（大写字母 B）。", "^^字长^^：==计算机一次能处理的二进制位数，或指运算器和寄存器的宽度。==字长为 32 位的 CPU 所在计算机称为 32 位机，这里的 32 位就是字长，通常也可称为双字。", "^^基本换算^^：==1B = 8b==。", "13、==计算机的存储程序控制工作原理==：==迄今为止==，计算机按照美籍匈牙利数学家冯·诺依曼提出的“存储程序控制”原理工作：一个问题的运算步骤（程序）连同它所处理的数据都用二进制表示，并预先存放在存储器中。程序运行时，CPU 从内存中一条一条地取出指令和相应的数据，按指令操作码的规定对数据进行运算处理，直到程序执行完毕。"], "title": "", "ordered": false}, {"t": "callout", "id": "a1-1-4-2-b8", "imp": "core", "kind": "tip", "text": "鼠标按工作原理分为：机械滚球鼠标（已淘汰）、光电鼠标（红外发光二极管）、激光鼠标（精度更高适配表面广）；现代鼠标主流采用 ==USB 接口、2.4GHz 无线接收器接口或蓝牙接口==，传统台式机的绿色 PS/2 圆口已逐步退出市场。", "title": "考向复习提示：鼠标工作原理与常见物理接口"}, {"t": "callout", "id": "a1-1-4-2-b9", "imp": "core", "kind": "trap", "text": "光电鼠标底部并不是“测量鼠标移动位移”，而是依靠底部的微型 CMOS 传感器==高速连续拍摄工作面的微观图像，由内置 DSP 图像处理器对比前后两张图像的特征点位移差==，从而计算出移动方向与距离；切勿选错为滚轴机械计数或反射强度积分。", "title": "高频易错陷阱：光电鼠标定位机理认知误区"}]$p0b_54$::jsonb, '', $p0s_54$1、键盘（字符与命令输入设备）
（1）向计算机输入字母、数字、符号、命令等信息
（2）布局：功能键（ESC、F1~F12）、打字键盘（字母键、数字键、符号、修饰键（Ctrl、Shift、Alt 等））、光标控制键、小键盘（数字、数学运算符号等）、其他键（Windows 控制键、多媒体播放控制键等）
（3）键盘是计算机必不可少的输入设备
（4）为了方便盲打，键盘上有两个定位，分别是“F”键和“J”键
（5）键盘有机械式（早期使用）和电容式（目前主流）。
（6）常用接口：USB(2.0、3.0)、PS/2（紫色接口）、无线接口（红外或者无线电波，需接收器插入USB接口）。
（7）电容式键盘特点：无磨损和接触不良问题，耐久性、灵敏度和稳定性都比较好，击键声音小，手感较好，寿命较长。
2、鼠标（命令输入设备）
（1）作用：控制屏幕上的鼠标箭头准确地定位在指定的位置处，然后通过按键（左键或右键）发出命令，完成各种操作。
（2）鼠标不是计算机必备输入设备，是常用输入设备。
（3）鼠标分类：机械式鼠标（过去使用）和光电式鼠标（目前主流）。
（4）光电式鼠标通过激光或红外线识别鼠标器移动的方向和距离
（5）光电鼠标使用微型镜头拍摄其下方的图像，由DSP（数字信号处理）分析判断鼠标器的移动方向和距离。
（6）鼠标的分辨率是指鼠标每移动1 英寸光标在屏幕上通过的像素数目。使用dip(dot per inch)表示。
（7）Windows 下常鼠标操作及功能：
①、单击左键：选择对象（Ctrl+左单：选择多个不连继的；Shift+左单：选择多个连续），或选择执行某个菜单
②、双击左键：打开文件/文件夹，或运行应用程序
③、左键拖放：移动对象/复制对象（Ctrl+左键拖）/创建对象快捷方式（Alt+左键拖）等
④、单击右键：弹出所指对象的快捷菜单
⑤、向前/向后转动滚轮：显示窗口中前面/后面的内容（滚屏）
（8）Windows 下常见鼠标状态：
(9)常用鼠标接口：RS-232(已不使用)、PS/2（绿色，很少使用）、USB（主流）、无线鼠标（需要接收器）
3、笔输入设备（手写板）
（1）作用：兼容有键盘、鼠标和写字笔的功能（可替代键盘、鼠标输入字符、命令和作图），输入汉字需要运行“手写汉字识别软件”。
（2）手写板分类：电阻式、电容式、电磁感应式
（3）电磁感应笔：电磁感应笔发出电磁波，基板接受到电磁波后计算出笔的位置信息，然后传送给主机，主机立刻在屏幕上显示出笔的运动轨迹。笔尖相当于鼠标左键、按钮1 相当于鼠标右键、按钮2 相当于鼠标滚轮。
（4）手写板接口：串行口、USB。
（5）触摸屏（现在使用的）是在液晶面板上覆盖一层压力板，它对压力很敏感，当手指或笔尖施压其上时会有电流产生以确定压力源的位置，并对其进行跟踪，然后通过软件识别出用户所输入的信息。
4、扫描仪（图像输入设备）
（1）扫描仪是将原稿（图片、照片、底片、书稿）输入计算机的一种输入设备
（2）扫描仪输入到计算机中的是原稿的“图象”(bitmap，格式为：TIF),不是图形
（3）工作原理（平板式）：进行光电转换（CCD 电荷耦合器件）, 产生电流并输出
（4）常见扫描仪类型：平板式、滚筒式和胶片专用、手持式扫描仪
（5）扫描仪主要性能指标：
①、光学分辨率（dpi）：反映图像大小，dpi 越高清晰。例如：1200×2400 dpi
②、色彩位数（色彩深度）：反映色彩逼真度，色彩位数越多，图像越真实。例如：32 bit
③、扫描幅面：指被扫描的原稿的尺寸（最大）；例如：A3、A4 等
④、与主机的接口类型：SCSI， USB，IEEE 1394 接口。
5、数码相机（图像输入设备）
（1）功能：获取现实世界中景物的数字图像
（2）成像芯片：CCD（电荷耦合器）或CMOS（互补金属氧化物半导体）
（3）与传统相机的镜头、快门等设备基本相同
（4）数码相机默认使用JPG（JPEG 的简称）格式。但有些专业摄影师会使用高级相机拍RAW 格式，是一种无损压缩图像格式。
（5）性能指标：分辨率（dpi）、存储容量（存储容量越大，并不一定存储图像越多，还要看单个图像的分辨率）。
（6）接口：USB、IEEE 1394 接口。
6、摄像头（视频输入设备）
（1）是一种视频输入设备，获取现实世界中景物的连续图像数字化输送至计算机中进行处理。
（2）分类：数字摄像头和模拟摄像头
（3）主要组成部件 ：镜头、CCD/CMOS、电源
（4）性能指标：分辨率（dpi）、色域（RGB24、YUV）、图像压缩方式（静态JEPG）、彩色深度
（5）接口：RS232、USB、IEEE 1394 接口。
7、传感器（输入设备）
（1）传感器是一种检测装置，能将感到的被检测的信息，并将其换成电信号供计算机处理（测量、转换、存储、显示或传输）。
（2）触摸屏、摄像头、微型话筒等设备的核心都是传感器
8、在选定区选定行、段与全文：在文档左侧的选定区：单击鼠标左键选择一行；双击鼠标左键选择一段；三击鼠标左键选择整个文档。
9、用鼠标调整行高与列宽：将鼠标移到行（或列）的边框上，光标变为双向箭头时按住左键拖动，可调整行高（或列宽）；也可右击，在弹出的快捷菜单中选择“行高”或“列宽”。
10、功能键F1～F12的作用由前台程序决定：键盘上的12个功能键（F1～F12）的具体功能，由正在前台执行的程序决定。
11、平板式扫描仪工作原理：光源发出的光照射放在玻璃板上的被扫描原稿，原稿的反射光经反射镜反射后由镜头聚焦到 CCD 上，CCD（电荷耦合器件）进行光电转换，产生电流并输出；扫描臂沿扫描方向移动，逐行完成整幅原稿的扫描。
12、计算机中数据单位与字长
位（bit，比特）：表示信息的最小单位，1 bit 简写为 1b（小写字母 b）。
字节（Byte）：最常用的信息基本单位，1 Byte 简写为 1B（大写字母 B）。
字长：计算机一次能处理的二进制位数，或指运算器和寄存器的宽度。字长为 32 位的 CPU 所在计算机称为 32 位机，这里的 32 位就是字长，通常也可称为双字。
基本换算：1B = 8b。
13、计算机的存储程序控制工作原理：迄今为止，计算机按照美籍匈牙利数学家冯·诺依曼提出的“存储程序控制”原理工作：一个问题的运算步骤（程序）连同它所处理的数据都用二进制表示，并预先存放在存储器中。程序运行时，CPU 从内存中一条一条地取出指令和相应的数据，按指令操作码的规定对数据进行运算处理，直到程序执行完毕。
考向复习提示：鼠标工作原理与常见物理接口
鼠标按工作原理分为：机械滚球鼠标（已淘汰）、光电鼠标（红外发光二极管）、激光鼠标（精度更高适配表面广）；现代鼠标主流采用 USB 接口、2.4GHz 无线接收器接口或蓝牙接口，传统台式机的绿色 PS/2 圆口已逐步退出市场。
高频易错陷阱：光电鼠标定位机理认知误区
光电鼠标底部并不是“测量鼠标移动位移”，而是依靠底部的微型 CMOS 传感器高速连续拍摄工作面的微观图像，由内置 DSP 图像处理器对比前后两张图像的特征点位移差，从而计算出移动方向与距离；切勿选错为滚轴机械计数或反射强度积分。$p0s_54$, $p0r_54${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A1-1.4.2 键盘，鼠标的分类，工作原理，基本操作，采用的接口类型。", "题库补充：在选定区选定行、段与全文 (24题)", "题库补充：用鼠标调整行高与列宽 (18题)", "题库补充：功能键F1～F12的作用由前台程序决定 (14题)", "题库补充：平板式扫描仪工作原理 (12题)", "题库补充：计算机中数据单位与字长 (11题)", "题库补充：计算机的存储程序控制工作原理 (11题)", "p0_refine_20261113"], "pages": [17, 18, 19], "spans": 59}$p0r_54$::jsonb, NOW());
