  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (174, 4, $p0b_174$[{"t": "list", "id": "b2-2-2-4-b1", "imp": "core", "items": ["④、应用层是 ZigBee 无线网络中的最高协议层并且管理应用对象。生产商开发应用对象来为各种应用定制一款设备，在 ZigBee 设备中，应用对象控制和管理协议层，单个的设备中最多可以有 240 个应用对象。", "==（6）中国使用的Zigbee 工作频段是2.4GHz，定义16 信道；==", "==（7）在Zigbee 协议架构中属于IEEE802.15.4 标准定义的是物理层和MAC 层。==", "==（8）Zigbee 支持的网络拓扑结构：星型、树型 、网状。=="], "title": "", "ordered": false}, {"h": 292, "t": "img", "w": 588, "id": "b2-2-2-4-b2", "imp": "normal", "src": "/kb-assets/theory/p107_r0_7766c8cd919667af.png", "title": ""}, {"t": "list", "id": "b2-2-2-4-b3", "imp": "core", "items": ["1、WI-FI", "==（1）Wi-Fi 是一个无线网路通信技术的品牌，由 Wi-Fi 联盟（Wi-Fi Alliance）持有，目的是改善基于IEEE 802.11 标准的无线网络产品之间的互通性。==", "==（2）Wi-Fi 是一种可以将计算机、手持设备（如 PDA、手机）等终端以无线方式互相连接的技术。==", "==（3）优势：==", "==①、无线电波的覆盖范围广。==", "==②、传输速度非常快。==", "==③、厂商进入该领域的门槛比较低。==", "==（4）工作频段：2.4GHz。==", "==（5）连接WI-FI 过程：扫描网络、认证过程、关联过程==", "2、蓝牙", "==（1）蓝牙是一种支持设备短距离通信（一般 平均10m 内）的无线电技术，能够在包括移动电话、掌上电脑、无线耳机、笔记本电脑、相关外设等众多设备之间进行无线信息交换。==", "==（2）蓝牙技术的优势是稳定、全球可用、设备范围广、易于使用、采用了通用规格。==", "==（3）有两种蓝牙技术体系：Basic Rate (BR) 和 Low Energy (LE)。==", "==（4）蓝牙3.0 Bluetooth High Speed 技术可用于数据的高速传输，好比在设备间传输很大的音频或视频文件，批量下载照片等等。==", "==（5）Low Energy(LE，4.0)技术体系相比BR 技术具有低功耗，低复杂度，开支小，低速率等特点。==", "==（6）蓝牙和WiFi 都运行于2.4GHz 频率==", "==（7）其实蓝牙也可用于802.11b 那样可达百米级传输，但是更多用于短距的。==", "==（8）常见：蓝牙耳机、蓝牙音箱、蓝牙键盘鼠标等。==", "3、GPS 技术", "^^（1）GPS 即全球定位系统是利用定位卫星，在全球范围内实时进行定位、导航的系统。^^", "（2）全球四大卫星导航系统包括==美国的全球定位系统、俄罗斯的\"格洛纳斯\"系统、欧洲的\"伽利略\"系统和==@@中国的\"北斗\"系统@@。", "（3）最早由美国1973 年开始研制，起初完全是一个军用导航系统，从1983 年开始用于解决大地测量问题。系统的最终构成在1993/1944 年间完成的。", "（4）GPS 系统由三部分构成：", "^^①、空间部分（卫星星座）：主动式工作卫星（23 颗）、3 个备用卫星。^^", "^^②、控制部分（地面控制系统）：一个主控站，三个注入站，五个监测站组成。^^", "^^③、用户部分（信号接收处理）：不同类型的接收机和相关设备及软件等。^^"], "title": "", "ordered": false}, {"h": 387, "t": "img", "w": 774, "id": "b2-2-2-4-b4", "imp": "normal", "src": "/kb-assets/theory/p108_r0_6a014ff40cf81138.png", "title": ""}, {"t": "list", "id": "b2-2-2-4-b5", "imp": "core", "items": ["（5）@@北斗系统@@", "==①、由5 颗静止轨道卫星和30 颗非静止轨道卫星组成。==", "==②、“北斗一号”精确度在10 米之内，而“北斗二号”可以精确到“厘米”之内。==", "==③、在==@@物联网感知层面@@==，北斗系统的定位、授时功能可完成精准时间信息和位置信息感知的任务；==", "==④、在==@@物联网网络层面@@==，北斗系统的短报文通信功能可实现感知信息和控制信息的全天候、全天时、无缝隙传递。==", "4、==蓝牙和wifi，zigbee 的区别==", "（1）传输距离、速率、功耗不同", "==①、蓝牙：传输距离2-30M，速率1Mbps，功耗介于zigbee 和WIFI 之间。==", "==②、wifi：传输距离在100-300M，速率可达300Mbps，功耗10-50mA。==", "==③、zigbee：传输距离50-300M，速率250kbps，功耗5mA。==", "（2）应用范围不同", "==①、蓝牙：通信、汽车、多媒体、工业、医疗、教育等。==", "==②、wifi：无线上网、PC、PDA。==", "==③、zigbee：主要适合用于自动控制和远程控制领域，可以嵌入各种设备。==", "（3）特点不同", "==①、蓝牙：采用简单的GFSK 调制，拥有极低的运行和待机功耗，使用一粒纽扣电池甚至可连续工作数年之久。==", "==②、wifi：WiFi 的传输速度很快、健康安全WiFi 产品辐射小。==", "==③、zigbee：近距离、低复杂度、自组织、低功耗、低数据速率、低成本。==", "5、==物联网应用层关键技术==：==物联网应用层关键技术原理==，以及物联网应用与云计算、大数据、人工智能等技术的融合。", "6、^^物联网应用层的关键技术^^：物联网应用层关键技术主要包括^^云计算、软件和算法、信息和隐私安全技术、标识和解析技术^^。 云计算具有弹性收缩、快速部署、资源抽象和按用量收费的特性，按照云计算的服务类型可以将云分为三层：基础架构即服务、平台即服务、软件即服务。 软件和算法在物联网的信息处理和应用集成中发挥重要作用，是物联网智慧性的集中体现。其中的关键技术主要包括面向服务的体系架构（SOA）和中间件技术，重点包括各种物联网计算系统的感知信息处理、交互与优化软件与算法、物联网计算系统体系结构与软件平台研发等。", "7、^^数据库与数据挖掘技术^^：^^通过建立能够全面捕捉物联网数据的分布式时空数据库^^，基于云计算平台对物联网系统的数据进行全面挖掘：对相关数据进行分析研究，从而使物联网的数据挖掘工作得以良好执行与完成。"], "title": "", "ordered": false}, {"t": "callout", "id": "b2-2-2-4-b6", "imp": "core", "kind": "tip", "text": "物联网是物理世界数字化的输入端（产生海量实时流式数据），==云计算为物联网提供无限弹性的分布式存储与计算算力支撑，大数据技术负责从海量传感时序数据中清洗挖掘业务规律，人工智能（AIoT）则为物联网注入实时决策与智能控制能力==；四者形成有机闭环系统。", "title": "考向复习提示：物联网与云计算/大数据/AI 的深度技术融合"}, {"t": "callout", "id": "b2-2-2-4-b7", "imp": "core", "kind": "trap", "text": "物联网产生的数据体量极其巨大，如果把所有工业摄像头的高清视频或自动驾驶车辆的雷达数据全部上传到远程云端中心处理，会导致骨干网络严重拥堵且传输时延过高（无法满足毫秒级刹车控制）；因此==在靠近数据源头的网络边缘网关就近执行低时延数据预处理与分析的“边缘计算”成为现代物联网不可或缺的架构==！", "title": "高频易错陷阱：边缘计算（Edge Computing）在物联网中的必要性"}]$p0b_174$::jsonb, '', $p0s_174$④、应用层是 ZigBee 无线网络中的最高协议层并且管理应用对象。生产商开发应用对象来为各种应用定制一款设备，在 ZigBee 设备中，应用对象控制和管理协议层，单个的设备中最多可以有 240 个应用对象。
（6）中国使用的Zigbee 工作频段是2.4GHz，定义16 信道；
（7）在Zigbee 协议架构中属于IEEE802.15.4 标准定义的是物理层和MAC 层。
（8）Zigbee 支持的网络拓扑结构：星型、树型 、网状。
1、WI-FI
（1）Wi-Fi 是一个无线网路通信技术的品牌，由 Wi-Fi 联盟（Wi-Fi Alliance）持有，目的是改善基于IEEE 802.11 标准的无线网络产品之间的互通性。
（2）Wi-Fi 是一种可以将计算机、手持设备（如 PDA、手机）等终端以无线方式互相连接的技术。
（3）优势：
①、无线电波的覆盖范围广。
②、传输速度非常快。
③、厂商进入该领域的门槛比较低。
（4）工作频段：2.4GHz。
（5）连接WI-FI 过程：扫描网络、认证过程、关联过程
2、蓝牙
（1）蓝牙是一种支持设备短距离通信（一般 平均10m 内）的无线电技术，能够在包括移动电话、掌上电脑、无线耳机、笔记本电脑、相关外设等众多设备之间进行无线信息交换。
（2）蓝牙技术的优势是稳定、全球可用、设备范围广、易于使用、采用了通用规格。
（3）有两种蓝牙技术体系：Basic Rate (BR) 和 Low Energy (LE)。
（4）蓝牙3.0 Bluetooth High Speed 技术可用于数据的高速传输，好比在设备间传输很大的音频或视频文件，批量下载照片等等。
（5）Low Energy(LE，4.0)技术体系相比BR 技术具有低功耗，低复杂度，开支小，低速率等特点。
（6）蓝牙和WiFi 都运行于2.4GHz 频率
（7）其实蓝牙也可用于802.11b 那样可达百米级传输，但是更多用于短距的。
（8）常见：蓝牙耳机、蓝牙音箱、蓝牙键盘鼠标等。
3、GPS 技术
（1）GPS 即全球定位系统是利用定位卫星，在全球范围内实时进行定位、导航的系统。
（2）全球四大卫星导航系统包括美国的全球定位系统、俄罗斯的"格洛纳斯"系统、欧洲的"伽利略"系统和中国的"北斗"系统。
（3）最早由美国1973 年开始研制，起初完全是一个军用导航系统，从1983 年开始用于解决大地测量问题。系统的最终构成在1993/1944 年间完成的。
（4）GPS 系统由三部分构成：
①、空间部分（卫星星座）：主动式工作卫星（23 颗）、3 个备用卫星。
②、控制部分（地面控制系统）：一个主控站，三个注入站，五个监测站组成。
③、用户部分（信号接收处理）：不同类型的接收机和相关设备及软件等。
（5）北斗系统
①、由5 颗静止轨道卫星和30 颗非静止轨道卫星组成。
②、“北斗一号”精确度在10 米之内，而“北斗二号”可以精确到“厘米”之内。
③、在物联网感知层面，北斗系统的定位、授时功能可完成精准时间信息和位置信息感知的任务；
④、在物联网网络层面，北斗系统的短报文通信功能可实现感知信息和控制信息的全天候、全天时、无缝隙传递。
4、蓝牙和wifi，zigbee 的区别
（1）传输距离、速率、功耗不同
①、蓝牙：传输距离2-30M，速率1Mbps，功耗介于zigbee 和WIFI 之间。
②、wifi：传输距离在100-300M，速率可达300Mbps，功耗10-50mA。
③、zigbee：传输距离50-300M，速率250kbps，功耗5mA。
（2）应用范围不同
①、蓝牙：通信、汽车、多媒体、工业、医疗、教育等。
②、wifi：无线上网、PC、PDA。
③、zigbee：主要适合用于自动控制和远程控制领域，可以嵌入各种设备。
（3）特点不同
①、蓝牙：采用简单的GFSK 调制，拥有极低的运行和待机功耗，使用一粒纽扣电池甚至可连续工作数年之久。
②、wifi：WiFi 的传输速度很快、健康安全WiFi 产品辐射小。
③、zigbee：近距离、低复杂度、自组织、低功耗、低数据速率、低成本。
5、物联网应用层关键技术：物联网应用层关键技术原理，以及物联网应用与云计算、大数据、人工智能等技术的融合。
6、物联网应用层的关键技术：物联网应用层关键技术主要包括云计算、软件和算法、信息和隐私安全技术、标识和解析技术。 云计算具有弹性收缩、快速部署、资源抽象和按用量收费的特性，按照云计算的服务类型可以将云分为三层：基础架构即服务、平台即服务、软件即服务。 软件和算法在物联网的信息处理和应用集成中发挥重要作用，是物联网智慧性的集中体现。其中的关键技术主要包括面向服务的体系架构（SOA）和中间件技术，重点包括各种物联网计算系统的感知信息处理、交互与优化软件与算法、物联网计算系统体系结构与软件平台研发等。
7、数据库与数据挖掘技术：通过建立能够全面捕捉物联网数据的分布式时空数据库，基于云计算平台对物联网系统的数据进行全面挖掘：对相关数据进行分析研究，从而使物联网的数据挖掘工作得以良好执行与完成。
考向复习提示：物联网与云计算/大数据/AI 的深度技术融合
物联网是物理世界数字化的输入端（产生海量实时流式数据），云计算为物联网提供无限弹性的分布式存储与计算算力支撑，大数据技术负责从海量传感时序数据中清洗挖掘业务规律，人工智能（AIoT）则为物联网注入实时决策与智能控制能力；四者形成有机闭环系统。
高频易错陷阱：边缘计算（Edge Computing）在物联网中的必要性
物联网产生的数据体量极其巨大，如果把所有工业摄像头的高清视频或自动驾驶车辆的雷达数据全部上传到远程云端中心处理，会导致骨干网络严重拥堵且传输时延过高（无法满足毫秒级刹车控制）；因此在靠近数据源头的网络边缘网关就近执行低时延数据预处理与分析的“边缘计算”成为现代物联网不可或缺的架构！$p0s_174$, $p0r_174${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B2-2.2.4 物联网应用层关键技术原理，物联网应用与云计算、大数据、人工智能等技术的融合。", "题库补充：物联网应用层关键技术 (10题)", "题库补充：物联网应用层的关键技术 (8题)", "题库补充：数据库与数据挖掘技术 (5题)", "p0_refine_20261113"], "pages": [107, 108], "spans": 52}$p0r_174$::jsonb, NOW());
