-- Node 226 (B6-6.3.2) rev 3 -> 4
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 3;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 226 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 226: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (226, 4, $p0b_226$[{"t": "list", "id": "b6-6-3-2-b1", "imp": "core", "items": ["人工智能在智能家居领域中的应用场景有：", "（1）==智能音箱==：通过语音识别、语音合成、自然语言处理等来实现与人交互，进行聊天、播放音乐、讲故事、查询信息等；", "（2）==智能门锁==：通过人脸识别、机器视觉等技术来实现智能的管理门锁。", "（3）==扫地机器人==：应用了计算机视觉来进行导航等", "（4）==家庭监控==：计算机视觉识别来进行监控家庭、也有可以进行防火防盗功能", "（5）==家庭康复机器人==：通过语音识别、自然语言处理等对家里老人孩子进行监护，提醒吃饭、吃药、起床等服务。", "（6）==健康检测==：通过穿戴设备收集的信息进行健康体征，可以进行智能提醒等。", "1、==AI 在智能交通领域应用==AI 在智能交通领域的应用，主要集中在综合执法、公共交通、交通秩序管控、智慧出行、智慧停车等领域，尤其是AI 交管，是最具代表性的场景应用。 AI 交管，主要集中在交通秩序管控和交通行为管控两个方面。", "（1）==交通秩序管控==:主要治理思路是做交通疏导，利用大数据分析道路交通状态并做交通诱导、红绿灯信号控制等，通过AI 算法对路口运行效率进行实时监测，通过优化信号灯配时，提高通行效率。", "（2）==交通行为管控:==通过AI 前端采集设备，抓拍不文明交通行为，如机动车加塞变道、随意停车、闯禁行，非机动车闯红灯、逆行，行人闯红灯等。 AI 摄像机借助深度学习技术，能实现交通违法行为的分析判断，可以对车辆、人脸进行识别，对数据进行储存，通过大数据和人工智能算法技术可以对几十种违法行为进行分析和取证，从而完成对交通违章违法行为的研判和取证。", "（3）==智慧出行==：通过AI 相关技术进行分析，实现公众出行多模式多标准动态导航，提高出行效率等。", "（4）==智慧停车==：基于AI 和大数据的无感支付停车，不仅改变了传统停车支付模式，也彻底改变了传统停车生态。", "2、==AI 在智能制造领域应用==目前制造企业中应用的人工智能技术，主要围绕在智能语音交互产品、人脸识别、图像识别、图像搜索、声纹识别、文字识别、机器翻译、机器学习、大数据计算、数据可视化等方面。", "（1）==智能分拣==：利用工业机器人进行快速分检，可以大幅减低成本，提高速度。", "（2）==设备健康管理==：利用特征分析和机器学习技术，可以预测故障，减少非计划停机。", "（3）==基于视觉的表面缺陷检测==：利用机器视觉可以识别出微小的缺陷，并进行分类处理。", "（4）==基于声纹的产品质量检测与故障判断==：利用声纹识别技术实现异音的自动检测，发现不良品等。", "（5）==智能决策==：应用机器学习等人工智能技术，结合大数据分析，优化调度方式，提升企业决策能力。", "3、==AI 在智慧医疗领域应用==人工智能在智慧医疗领域应用主要是临床辅助决策系统、医疗大数据治理、眼底影像分析系统、智能诊前助手等。", "（1）==临床辅助决策系统==：通过学海量教材、临床指南、药典及三甲医院优质病历，基于自然语言处理、知识图谱等多种AI 技术来进行辅助诊断、治疗方案推荐、相似病历推荐、医嘱质控、病历内涵质控、医学知识查询、辅助问诊等服务。", "（2）==医疗大数据治理==：助力医疗基础数据资源建设、使电子病历形式规范化，互操作性强等；通过大数据解决方案，可实现多层级病历结构化，全面支持临床、科研、管理等场景下的医疗数据应用。", "（3）==眼底影像分析系统==：基于扎实的眼底影像数据基础，整合循证医学可解释算法架构及深度学习高准确率算法构造眼底影像分析系统，能帮助及早发现糖尿病视网膜病变、青光眼、黄斑病变等主要致盲疾病，避免致盲风险。", "（4）==智能诊前助手==：基于专业医疗知识图谱，采用多种算法模型与多轮智能交互理解病人病情，根据病人病情精准匹配就诊科室和专业医生。整体问诊识别率及准确率均超过95%。", "4、==AI 在智慧金融领域应用==在智慧金融领域的应用有智能外呼机器人、智能机器人、声纹反欺诈系统、智能质检分析系统、全渠道全流程的智能客服等；", "（1）==智能外呼机器人==：利用智能人机交互技术，让机器替代人工完成流程规范、话术统一的外呼工作，释放人力处理难度大、产值高的工作，提高人员的工作效率，节省企业成本。应用场景：营销获客、风险控制、运营管理等；", "（2）==智能机器人==：能够自动化智能化地执行重复性业务流程，提升人员工作效率。场景：金融辅助审核、金融业务申请资料处理等；", "（3）==声纹反欺诈系统==：应用于风险控制场景，主要功能单元有声纹检索、声纹预警、声纹聚类等，采取多种识别模型，通过与音频数据、业务系统信息等核验，防止和发现欺诈行为。", "（4）==智能质检分析系统==：对海量的人人通话录音进行质检与数据分析，发现引发客户投诉的矛盾点和对外服务的短板，挖掘客户关注热点和营销热点，为提升服务质量提供数据支撑。", "（5）==全渠道全流程的智能客服==：面向金融机构客户服务部门，通过语音识别、自然语言理解技术，实现机器代替人工服务客户的功能，提升客户体验，降低企业成本，避免人员流失。", "5、==AI 在智慧教育领域应用智慧教育==：==基于语音交互、文字识别、人脸识别、人体识别、AR 等多项AI 技术，赋能软硬件教学产品，实现更好的人机交互的教学体验，用更低的师资成本获得高质量的教育效果；==同时打造智慧校园，实现校园安全、校内考勤、课堂效果监测等关键场景业务升级，提升校园生活体验和安全性，降低管理成本。", "==业务服务场景有：作业辅导批改、作文批发、语音辅助教学、智能辅助教学、教育直播审核、课堂专注度分析、考生远程身份认证、人员通行管理、学生自助服务、校园安防、考勤管理等。==", "6、==人工智能应用领域与企业布局==：百度——无人驾驶 阿里——ET城市大脑 腾讯——医疗影像 科大讯飞——智能语音 人工智能还可应用于智能家居、智慧零售、智慧交通、智慧医疗、智慧教育、智慧物流、智慧安防等领域。", "7、^^人工智能与物联网的关系^^：^^物联网主要是控制终端与芯片的通信^^，人工智能主要是算法。物联网是由遵循相同协议的终端进行信息交互并合作完成一件事，人工智能则是不断自我学习、知识越来越多、越来越聪明的算法。 人工智能类似软件，需要物联网作为载体；物联网类似硬件，需要人工智能来驱动。人工智能需要落地的应用作为载体，物联网就是最重要的载体。物联网感知设备每天产生大量数据，如何利用和分析这些数据成为难题，人工智能的分析方法为此提供了解决方案：通过强大的数据分析能力，在人的帮助下做出最佳决策。人工智能与物联网融合、利用人工智能实时分析数据的物联网终端正走入千家万户。", "8、^^智能交通与无人驾驶^^：智能交通系统是通信、信息和控制技术在交通系统中集成应用的产物。ITS应用最广泛的地区是日本，其次是美国和欧洲等地区。目前，我国在ITS方面的应用主要是对交通中的车辆流量、行车速度进行采集和分析，从而对交通实施监控和调度，有效提高通行能力、简化交通管理、降低环境污染。 无人驾驶汽车是通过电脑系统实现无人驾驶的智能汽车，依靠人工智能、视觉计算、雷达、监控装置和全球定位系统协同合作，让电脑自动安全地操作汽车。", "9、^^人工智能在各领域的典型应用^^：==智能家居==：^^基于物联网技术^^，通过智能硬件、软件系统、云计算平台构成一套完整的家居生态圈。 智能制造：常见于质量监控、工艺流程优化、物流传输优化等环节。 智慧医疗：自动找到医学影像中的重点部位并对比分析，为医生诊断提供参考信息，减少误诊或漏诊。"], "title": "", "ordered": false}, {"t": "callout", "id": "b6-6-3-2-b2", "imp": "core", "kind": "tip", "text": "AI 落地生根：==智慧交通（自动驾驶辅助系统 ADAS、红绿灯信控优化）、智能家居（智能音箱语音中控）、智能制造（工业机器视觉缺陷检测）、智慧金融（智能量化交易、刷脸支付）、智慧医疗（AI 辅助阅片诊断肿瘤）、智慧教育（个性化自适应题库学习）==。", "title": "考向复习提示：人工智能赋能千行百业的典型落地"}, {"t": "callout", "id": "b6-6-3-2-b3", "imp": "core", "kind": "trap", "text": "国际汽车工程师学会（SAE）将自动驾驶分为 6 个等级（L0~L5）： • L0（全人工驾驶）； • L1~L2（驾驶辅助/部分自动化，责任主体依然是人类驾驶员）； • ==L3（有条件自动化，系统负责驾驶，人类在请求时接管）==； • ==L4（高度自动化，限定区域/场景无需人类接管）==； • ==L5（完全自动化，任何工况全无人驾驶）==；常考 L2 与 L3 的责任分界线！", "title": "高频易错陷阱：自动驾驶的分级标准（L0 ~ L5）"}]$p0b_226$::jsonb, '', $p0s_226$人工智能在智能家居领域中的应用场景有：
（1）智能音箱：通过语音识别、语音合成、自然语言处理等来实现与人交互，进行聊天、播放音乐、讲故事、查询信息等；
（2）智能门锁：通过人脸识别、机器视觉等技术来实现智能的管理门锁。
（3）扫地机器人：应用了计算机视觉来进行导航等
（4）家庭监控：计算机视觉识别来进行监控家庭、也有可以进行防火防盗功能
（5）家庭康复机器人：通过语音识别、自然语言处理等对家里老人孩子进行监护，提醒吃饭、吃药、起床等服务。
（6）健康检测：通过穿戴设备收集的信息进行健康体征，可以进行智能提醒等。
1、AI 在智能交通领域应用AI 在智能交通领域的应用，主要集中在综合执法、公共交通、交通秩序管控、智慧出行、智慧停车等领域，尤其是AI 交管，是最具代表性的场景应用。 AI 交管，主要集中在交通秩序管控和交通行为管控两个方面。
（1）交通秩序管控:主要治理思路是做交通疏导，利用大数据分析道路交通状态并做交通诱导、红绿灯信号控制等，通过AI 算法对路口运行效率进行实时监测，通过优化信号灯配时，提高通行效率。
（2）交通行为管控:通过AI 前端采集设备，抓拍不文明交通行为，如机动车加塞变道、随意停车、闯禁行，非机动车闯红灯、逆行，行人闯红灯等。 AI 摄像机借助深度学习技术，能实现交通违法行为的分析判断，可以对车辆、人脸进行识别，对数据进行储存，通过大数据和人工智能算法技术可以对几十种违法行为进行分析和取证，从而完成对交通违章违法行为的研判和取证。
（3）智慧出行：通过AI 相关技术进行分析，实现公众出行多模式多标准动态导航，提高出行效率等。
（4）智慧停车：基于AI 和大数据的无感支付停车，不仅改变了传统停车支付模式，也彻底改变了传统停车生态。
2、AI 在智能制造领域应用目前制造企业中应用的人工智能技术，主要围绕在智能语音交互产品、人脸识别、图像识别、图像搜索、声纹识别、文字识别、机器翻译、机器学习、大数据计算、数据可视化等方面。
（1）智能分拣：利用工业机器人进行快速分检，可以大幅减低成本，提高速度。
（2）设备健康管理：利用特征分析和机器学习技术，可以预测故障，减少非计划停机。
（3）基于视觉的表面缺陷检测：利用机器视觉可以识别出微小的缺陷，并进行分类处理。
（4）基于声纹的产品质量检测与故障判断：利用声纹识别技术实现异音的自动检测，发现不良品等。
（5）智能决策：应用机器学习等人工智能技术，结合大数据分析，优化调度方式，提升企业决策能力。
3、AI 在智慧医疗领域应用人工智能在智慧医疗领域应用主要是临床辅助决策系统、医疗大数据治理、眼底影像分析系统、智能诊前助手等。
（1）临床辅助决策系统：通过学海量教材、临床指南、药典及三甲医院优质病历，基于自然语言处理、知识图谱等多种AI 技术来进行辅助诊断、治疗方案推荐、相似病历推荐、医嘱质控、病历内涵质控、医学知识查询、辅助问诊等服务。
（2）医疗大数据治理：助力医疗基础数据资源建设、使电子病历形式规范化，互操作性强等；通过大数据解决方案，可实现多层级病历结构化，全面支持临床、科研、管理等场景下的医疗数据应用。
（3）眼底影像分析系统：基于扎实的眼底影像数据基础，整合循证医学可解释算法架构及深度学习高准确率算法构造眼底影像分析系统，能帮助及早发现糖尿病视网膜病变、青光眼、黄斑病变等主要致盲疾病，避免致盲风险。
（4）智能诊前助手：基于专业医疗知识图谱，采用多种算法模型与多轮智能交互理解病人病情，根据病人病情精准匹配就诊科室和专业医生。整体问诊识别率及准确率均超过95%。
4、AI 在智慧金融领域应用在智慧金融领域的应用有智能外呼机器人、智能机器人、声纹反欺诈系统、智能质检分析系统、全渠道全流程的智能客服等；
（1）智能外呼机器人：利用智能人机交互技术，让机器替代人工完成流程规范、话术统一的外呼工作，释放人力处理难度大、产值高的工作，提高人员的工作效率，节省企业成本。应用场景：营销获客、风险控制、运营管理等；
（2）智能机器人：能够自动化智能化地执行重复性业务流程，提升人员工作效率。场景：金融辅助审核、金融业务申请资料处理等；
（3）声纹反欺诈系统：应用于风险控制场景，主要功能单元有声纹检索、声纹预警、声纹聚类等，采取多种识别模型，通过与音频数据、业务系统信息等核验，防止和发现欺诈行为。
（4）智能质检分析系统：对海量的人人通话录音进行质检与数据分析，发现引发客户投诉的矛盾点和对外服务的短板，挖掘客户关注热点和营销热点，为提升服务质量提供数据支撑。
（5）全渠道全流程的智能客服：面向金融机构客户服务部门，通过语音识别、自然语言理解技术，实现机器代替人工服务客户的功能，提升客户体验，降低企业成本，避免人员流失。
5、AI 在智慧教育领域应用智慧教育：基于语音交互、文字识别、人脸识别、人体识别、AR 等多项AI 技术，赋能软硬件教学产品，实现更好的人机交互的教学体验，用更低的师资成本获得高质量的教育效果；同时打造智慧校园，实现校园安全、校内考勤、课堂效果监测等关键场景业务升级，提升校园生活体验和安全性，降低管理成本。
业务服务场景有：作业辅导批改、作文批发、语音辅助教学、智能辅助教学、教育直播审核、课堂专注度分析、考生远程身份认证、人员通行管理、学生自助服务、校园安防、考勤管理等。
6、人工智能应用领域与企业布局：百度——无人驾驶 阿里——ET城市大脑 腾讯——医疗影像 科大讯飞——智能语音 人工智能还可应用于智能家居、智慧零售、智慧交通、智慧医疗、智慧教育、智慧物流、智慧安防等领域。
7、人工智能与物联网的关系：物联网主要是控制终端与芯片的通信，人工智能主要是算法。物联网是由遵循相同协议的终端进行信息交互并合作完成一件事，人工智能则是不断自我学习、知识越来越多、越来越聪明的算法。 人工智能类似软件，需要物联网作为载体；物联网类似硬件，需要人工智能来驱动。人工智能需要落地的应用作为载体，物联网就是最重要的载体。物联网感知设备每天产生大量数据，如何利用和分析这些数据成为难题，人工智能的分析方法为此提供了解决方案：通过强大的数据分析能力，在人的帮助下做出最佳决策。人工智能与物联网融合、利用人工智能实时分析数据的物联网终端正走入千家万户。
8、智能交通与无人驾驶：智能交通系统是通信、信息和控制技术在交通系统中集成应用的产物。ITS应用最广泛的地区是日本，其次是美国和欧洲等地区。目前，我国在ITS方面的应用主要是对交通中的车辆流量、行车速度进行采集和分析，从而对交通实施监控和调度，有效提高通行能力、简化交通管理、降低环境污染。 无人驾驶汽车是通过电脑系统实现无人驾驶的智能汽车，依靠人工智能、视觉计算、雷达、监控装置和全球定位系统协同合作，让电脑自动安全地操作汽车。
9、人工智能在各领域的典型应用：智能家居：基于物联网技术，通过智能硬件、软件系统、云计算平台构成一套完整的家居生态圈。 智能制造：常见于质量监控、工艺流程优化、物流传输优化等环节。 智慧医疗：自动找到医学影像中的重点部位并对比分析，为医生诊断提供参考信息，减少误诊或漏诊。
考向复习提示：人工智能赋能千行百业的典型落地
AI 落地生根：智慧交通（自动驾驶辅助系统 ADAS、红绿灯信控优化）、智能家居（智能音箱语音中控）、智能制造（工业机器视觉缺陷检测）、智慧金融（智能量化交易、刷脸支付）、智慧医疗（AI 辅助阅片诊断肿瘤）、智慧教育（个性化自适应题库学习）。
高频易错陷阱：自动驾驶的分级标准（L0 ~ L5）
国际汽车工程师学会（SAE）将自动驾驶分为 6 个等级（L0~L5）： • L0（全人工驾驶）； • L1~L2（驾驶辅助/部分自动化，责任主体依然是人类驾驶员）； • L3（有条件自动化，系统负责驾驶，人类在请求时接管）； • L4（高度自动化，限定区域/场景无需人类接管）； • L5（完全自动化，任何工况全无人驾驶）；常考 L2 与 L3 的责任分界线！$p0s_226$, $p0r_226${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B6-6.3.2 人工智能在智能家居、智能交通、智能制造、智慧医疗、智慧金融、智慧教育等领域应用。", "题库补充：人工智能应用领域与企业布局 (12题)", "题库补充：人工智能与物联网的关系 (5题)", "题库补充：智能交通与无人驾驶 (5题)", "题库补充：人工智能在各领域的典型应用 (5题)", "p0_refine_20261113"], "pages": [131, 132, 133], "spans": 42}$p0r_226$::jsonb, NOW());
