-- Node 271 (S2-1.1) rev 3 -> 4
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 3;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 271 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 271: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (271, 4, $p0b_271$[{"t": "list", "id": "s2-1-1-b1", "imp": "normal", "items": ["1、数据库系统"], "title": "", "ordered": false}, {"h": 403, "t": "img", "w": 1062, "id": "s2-1-1-b2", "imp": "normal", "src": "/kb-assets/skill/p61_r0_e9eabfd371d2f3b5.png", "title": ""}, {"t": "list", "id": "s2-1-1-b3", "imp": "core", "items": ["2、==表==", "（1）表是一种有结构化的文件。", "（2）表（table） ：某种特定类型数据的结构化清单。", "==（3）在数据库中可以创建多个文件名，且文件名不能重复，是唯一的标识。==", "==（4）模式（schema）： 关于数据库和表的布局及特性的信息==", "==（5）关系可以表示为一个二维的表。==", "==（6）表有记录（元组）、列（属性、码、字段）等=="], "title": "", "ordered": false}, {"h": 312, "t": "img", "w": 594, "id": "s2-1-1-b4", "imp": "normal", "src": "/kb-assets/skill/p61_r1_70ccd35402e1758f.png", "title": ""}, {"t": "list", "id": "s2-1-1-b5", "imp": "core", "items": ["3、==列==", "（1）==表由列组成==。==列中存储着表中某部分的信息==。", "（2）==列（column）是表中的一个字段。==", "（3）==所有表都是由一个或多个列组成的==。", "（4）==可以使用SELECT（投影）显示列。=="], "title": "", "ordered": false}, {"h": 286, "t": "img", "w": 571, "id": "s2-1-1-b6", "imp": "normal", "src": "/kb-assets/skill/p61_r2_0bf10466fba41b1f.png", "title": ""}, {"t": "list", "id": "s2-1-1-b7", "imp": "core", "items": ["4、==行==", "==（1）行（row） 表中的一个记录==", "==（2）一个表中可以有0 或多条记录。数据量越大，查询的速度就会慢，所以可以对索引的使用、使用合适的数据类型来等提升或优化查询速度。==", "==（3）可以通过WHERE（选择）语句将记录筛选出来。=="], "title": "", "ordered": false}, {"h": 378, "t": "img", "w": 712, "id": "s2-1-1-b8", "imp": "normal", "src": "/kb-assets/skill/p62_r0_2aad611d496e97b0.png", "title": ""}, {"t": "list", "id": "s2-1-1-b9", "imp": "core", "items": ["5、==主键==", "==（1）表中每一行都应该有可以唯一标识自己的一列（或一组列）==", "==（2）一个表只能有一个主键。主键（主码、主关键字等）可以是一列或多列组成。==", "==（3）主键使用的SQL 中primary key（大小写不区分）来定义标识。==", "==（4）作用：主键实现唯一标识实体,主键实现实体完整性。==", "^^（5）比如学号、教师编号、区号、产品编号等^^"], "title": "", "ordered": false}, {"h": 273, "t": "img", "w": 914, "id": "s2-1-1-b10", "imp": "normal", "src": "/kb-assets/skill/p62_r1_03f654eed4ab8197.png", "title": ""}, {"t": "list", "id": "s2-1-1-b11", "imp": "core", "items": ["6、==外键==", "（1）==某表的一个主键,出现在另一个表中,那么这个主键在另一个表中的定义为外键（外码）。==", "（2）==作用：保持数据一致性，完整性，即数据参照完整性。==", "（3）==外键使用的SQL 中foreign key（大小写不区分）来定义标识。==", "（4）==一个表中可以有多个外键==。", "（5^^）比如成绩表中：教师编号、学号、课程号等者是成绩表的外键。^^", "7、==数据类型==", "==（1）数据库中每个列都有相应的数据类型。==", "==（2）数据类型定义列可以存储的数据种类。==", "^^（3）例如，如果列中存储的为数字（或许是订单中的物品数），则相应的数据类型应该为数值类型。如果列中存储的是日期、文本、注释、金额等，则应该用恰当的数据类型规定出来^^。", "（4）数据类型（datatype） 所容许的数据的类型。", "（5）==每个表列都有相应的数据类型，它限制（或容许）该列中存储的数据。=="], "title": "", "ordered": false}, {"h": 264, "t": "img", "w": 611, "id": "s2-1-1-b12", "imp": "normal", "src": "/kb-assets/skill/p62_r2_203586485cb978ff.png", "title": ""}, {"t": "list", "id": "s2-1-1-b13", "imp": "core", "items": ["8、==数据库设计阶段=="], "title": "", "ordered": false}, {"h": 618, "t": "img", "w": 1292, "id": "s2-1-1-b14", "imp": "normal", "src": "/kb-assets/skill/p63_r0_057d5a5dc1696787.png", "title": ""}, {"t": "list", "id": "s2-1-1-b15", "imp": "core", "items": ["9、==E-R 图==", "（1）==E-R 图也称实体-联系图(Entity Relationship Diagram)，提供了表示实体类型、属性和联系的方法，用来描述现实世界的概念模型。==", "（2）==联系的类型==：", "①、==1:1（一对一）==：比如身份证信息与人之间关系，一个人只能有一个身份证信息。", "②、==1:n（一对多）==：比如宿舍与学生之间关系；一个宿舍可以住多个学生居住。", "③、==m:n（多对多）==：比如学生与课程之间关系；一个学生可以选择多门课，一门课可以被多个学生选择", "（3）==图形表示==：", "①、==矩形框==：==表示实体型，矩形框内写明实体名称==；", "学生", "②、==椭圆图框：表示实体的属性，并用“实心线段”将其与相应关系的“实体型”连接起来，对于主属性（主键）名，则在其名称下划一下划线。==", "==主键下面有下划线==学号学生姓名", "③、==菱形框：表示实体型之间的联系成因，在菱形框内写明联系名，并用“实心线段”分别与有关实体型连接起来，同时在“实心线段”旁标上联系的类型=="], "title": "", "ordered": false}, {"h": 344, "t": "img", "w": 654, "id": "s2-1-1-b16", "imp": "normal", "src": "/kb-assets/skill/p63_r1_f5fdc4ca42fa899e.png", "title": ""}, {"t": "list", "id": "s2-1-1-b17", "imp": "core", "items": ["（4）画E-R 图的常用软件或工具：==visio、rose、word(插入形状)==等。", "10、绘制E-R 步骤", "^^（1）首先要找出实体，以及实体的相应属于^^", "^^（2）其次找到实体间存在的关系^^", "^^（3）最后按照E-R 图模型规则来绘制^^", "==11、一对一E-R 图举例==例1：两个实体集之间的一对一的联系的绘制方法。假设某学院有若干个系，每个系只有一名主任。则主任和系的属性分别如下：", "主任—编号，姓名，年龄，学历系—系编号，系名主任和系之间是一个管理关系，体现主任一个任职时间。如一对一E-R 图的示。", "==12、一对多E-R 图举例==例2：假设在某仓库管理系统中，有两个实体集：他库和商品。仓库用来存放商品，且规定一类商品只能存放在一个仓库中，一个仓库可以存放多件商品。", "仓库和商品之间是一对多的联系。", "仓库—仓库号，地点，面积联单商品—商品号，商品名，价格在存放联系中要反映出存放商品的数量。如一对多E-R 图的示。", "==13、多对多E-R 图举例==例3：假设在某教务管理系统中，一个教师可以上多门课，一门课也可以由多个老师去上。教师和课程之间是多对多的联系。教师和课程可用以下属性来描述：", "教师—教师号，教师名，职称课程—课程号，课程名，班级在“讲授”联系中应能反映出教师的授课程质量。如多对多E-R 图的示。"], "title": "", "ordered": false}, {"h": 757, "t": "img", "w": 1282, "id": "s2-1-1-b18", "imp": "normal", "src": "/kb-assets/skill/p64_r0_fe5eca1586619d07.png", "title": ""}, {"t": "list", "id": "s2-1-1-b19", "imp": "core", "items": ["==一对一E-R 图                       一对多E-R 图=="], "title": "", "ordered": false}, {"h": 882, "t": "img", "w": 682, "id": "s2-1-1-b20", "imp": "normal", "src": "/kb-assets/skill/p65_r0_f2dac47c3a547f06.png", "title": ""}, {"t": "list", "id": "s2-1-1-b21", "imp": "core", "items": ["==多对多E-R 图==2 创建数据库和表", "14、==数据库、DBMS 与 SQL 语言基础==：数据库（Database）是长期保存在计算机存储设备上、按照一定规则组织起来、可以被各种用户或应用共享的数据集合。 数据库管理系统（DataBase Management System，DBMS）是操作和管理数据库的大型软件，用于==建立、使用和维护数据库==，并对数据库进行统一管理和控制，以保证数据库的安全性和完整性；用户通过 DBMS 访问数据库中的数据。 MySQL 即 DBMS，负责管理真实的数据库；数据库中存放数据集合，包括表、视图等；表以二维行列存储数据，行（row）在 SQL 中称为一条记录（实体），列（column）称为字段。", "15、==关系数据模型的三类完整性规则==：^^关系数据模型有三类完整性规则^^：==“实体完整性”（主键不能为空值或重值）==；“引用完整性”（在关系中不允许引用不存在的实体元组）；“用户自定义完整性约束”（由应用环境对数据的需求而决定）。", "16、==存储模式（内模式）与 SQL 的非过程性==：^^存储模式（内模式）^^：==数据在数据库中的内部表示==，即对数据的物理结构和存储方式的描述。 综述：应用系统的全局关系模式对应于基本表，其存储结构对应于存储文件；面向用户的局部关系模式对应于视图或部分基本表。 SQL 包含对数据库的全部操作，用 SQL 语言可实现数据库应用过程中的全部活动。使用 SQL 只需指出需要哪类数据（做什么），不必指出获得这些数据的步骤（如何做）。", "17、==E-R 图的基本符号与联系类型==：==概念模型的建立方法是“实体-联系”方法==，即 E-R 图。 在 E-R 图中，矩形表示实体，椭圆表示属性，菱形表示表与表之间的联系。 E-R 概念模型中存在一对一、一对多、多对多三种联系。", "18、==系统设计阶段的三级结构设计==：^^“系统设计”阶段包括^^：==概念结构设计（E-R 图）==；逻辑结构设计（即关系模式设计）；物理结构设计（包含存储结构设计和程序结构设计）。", "19、==数据库控制与数据库保护==：", "^^1）数据库的破坏来自四个方面^^：系统故障、多用户并发访问数据库时造成数据的不一致、人为破坏、输入数据本身是错误的（或更新时造成数据错误）。", "^^2）通过四个方面来实现数据库控制（即数据库保护）^^：安全性控制、备份与恢复、完整性控制、并发控制。", "^^3）安全性控制^^：保护数据以防止不合法的使用。主要技术：", "①==用户标识与口令==；", "②访问控制（SQL 中的 GRANT 授权语句、REVOKE 取消授权语句用于==访问授权）==；", "③==审计；==", "④==数据加密==；", "⑤^^视图的保护。 4）备份与恢复^^：==实现技术是转储和日志==。数据库恢复的基本机制就是“冗余”，通过备份来重复存储数据库中的数据。"], "title": "", "ordered": false}, {"t": "callout", "id": "s2-1-1-b22", "imp": "core", "kind": "tip", "text": "E-R 图三大图元：==矩形表示实体集、椭圆形表示属性、菱形表示实体间的联系==；联系度包含 1:1、1:n 和 m:n 三种；转换规则：==一个 m:n 复合联系必须独立转换为一个单独的关系模式，其主键由两个相连实体的外键共同组成复合主键==。", "title": "考向复习提示：E-R 图三大核心图元与向关系模型转换规则"}, {"t": "callout", "id": "s2-1-1-b23", "imp": "core", "kind": "trap", "text": "专转本大题必考：当两个实体集之间存在 1:n 关联（如班级与学生）时，==必须将 1 端（班级）的主键作为外键添加到 n 端（学生表）中，而不是反过来把学生主键加到班级表中==！如果加反会导致班级表出现多值属性破坏关系规范化；多对多联系若漏掉将其独立建表更是扣分雷区！", "title": "高频易错陷阱：E-R 图转关系模式高频丢分点"}]$p0b_271$::jsonb, '', $p0s_271$1、数据库系统
2、表
（1）表是一种有结构化的文件。
（2）表（table） ：某种特定类型数据的结构化清单。
（3）在数据库中可以创建多个文件名，且文件名不能重复，是唯一的标识。
（4）模式（schema）： 关于数据库和表的布局及特性的信息
（5）关系可以表示为一个二维的表。
（6）表有记录（元组）、列（属性、码、字段）等
3、列
（1）表由列组成。列中存储着表中某部分的信息。
（2）列（column）是表中的一个字段。
（3）所有表都是由一个或多个列组成的。
（4）可以使用SELECT（投影）显示列。
4、行
（1）行（row） 表中的一个记录
（2）一个表中可以有0 或多条记录。数据量越大，查询的速度就会慢，所以可以对索引的使用、使用合适的数据类型来等提升或优化查询速度。
（3）可以通过WHERE（选择）语句将记录筛选出来。
5、主键
（1）表中每一行都应该有可以唯一标识自己的一列（或一组列）
（2）一个表只能有一个主键。主键（主码、主关键字等）可以是一列或多列组成。
（3）主键使用的SQL 中primary key（大小写不区分）来定义标识。
（4）作用：主键实现唯一标识实体,主键实现实体完整性。
（5）比如学号、教师编号、区号、产品编号等
6、外键
（1）某表的一个主键,出现在另一个表中,那么这个主键在另一个表中的定义为外键（外码）。
（2）作用：保持数据一致性，完整性，即数据参照完整性。
（3）外键使用的SQL 中foreign key（大小写不区分）来定义标识。
（4）一个表中可以有多个外键。
（5）比如成绩表中：教师编号、学号、课程号等者是成绩表的外键。
7、数据类型
（1）数据库中每个列都有相应的数据类型。
（2）数据类型定义列可以存储的数据种类。
（3）例如，如果列中存储的为数字（或许是订单中的物品数），则相应的数据类型应该为数值类型。如果列中存储的是日期、文本、注释、金额等，则应该用恰当的数据类型规定出来。
（4）数据类型（datatype） 所容许的数据的类型。
（5）每个表列都有相应的数据类型，它限制（或容许）该列中存储的数据。
8、数据库设计阶段
9、E-R 图
（1）E-R 图也称实体-联系图(Entity Relationship Diagram)，提供了表示实体类型、属性和联系的方法，用来描述现实世界的概念模型。
（2）联系的类型：
①、1:1（一对一）：比如身份证信息与人之间关系，一个人只能有一个身份证信息。
②、1:n（一对多）：比如宿舍与学生之间关系；一个宿舍可以住多个学生居住。
③、m:n（多对多）：比如学生与课程之间关系；一个学生可以选择多门课，一门课可以被多个学生选择
（3）图形表示：
①、矩形框：表示实体型，矩形框内写明实体名称；
学生
②、椭圆图框：表示实体的属性，并用“实心线段”将其与相应关系的“实体型”连接起来，对于主属性（主键）名，则在其名称下划一下划线。
主键下面有下划线学号学生姓名
③、菱形框：表示实体型之间的联系成因，在菱形框内写明联系名，并用“实心线段”分别与有关实体型连接起来，同时在“实心线段”旁标上联系的类型
（4）画E-R 图的常用软件或工具：visio、rose、word(插入形状)等。
10、绘制E-R 步骤
（1）首先要找出实体，以及实体的相应属于
（2）其次找到实体间存在的关系
（3）最后按照E-R 图模型规则来绘制
11、一对一E-R 图举例例1：两个实体集之间的一对一的联系的绘制方法。假设某学院有若干个系，每个系只有一名主任。则主任和系的属性分别如下：
主任—编号，姓名，年龄，学历系—系编号，系名主任和系之间是一个管理关系，体现主任一个任职时间。如一对一E-R 图的示。
12、一对多E-R 图举例例2：假设在某仓库管理系统中，有两个实体集：他库和商品。仓库用来存放商品，且规定一类商品只能存放在一个仓库中，一个仓库可以存放多件商品。
仓库和商品之间是一对多的联系。
仓库—仓库号，地点，面积联单商品—商品号，商品名，价格在存放联系中要反映出存放商品的数量。如一对多E-R 图的示。
13、多对多E-R 图举例例3：假设在某教务管理系统中，一个教师可以上多门课，一门课也可以由多个老师去上。教师和课程之间是多对多的联系。教师和课程可用以下属性来描述：
教师—教师号，教师名，职称课程—课程号，课程名，班级在“讲授”联系中应能反映出教师的授课程质量。如多对多E-R 图的示。
一对一E-R 图 一对多E-R 图
多对多E-R 图2 创建数据库和表
14、数据库、DBMS 与 SQL 语言基础：数据库（Database）是长期保存在计算机存储设备上、按照一定规则组织起来、可以被各种用户或应用共享的数据集合。 数据库管理系统（DataBase Management System，DBMS）是操作和管理数据库的大型软件，用于建立、使用和维护数据库，并对数据库进行统一管理和控制，以保证数据库的安全性和完整性；用户通过 DBMS 访问数据库中的数据。 MySQL 即 DBMS，负责管理真实的数据库；数据库中存放数据集合，包括表、视图等；表以二维行列存储数据，行（row）在 SQL 中称为一条记录（实体），列（column）称为字段。
15、关系数据模型的三类完整性规则：关系数据模型有三类完整性规则：“实体完整性”（主键不能为空值或重值）；“引用完整性”（在关系中不允许引用不存在的实体元组）；“用户自定义完整性约束”（由应用环境对数据的需求而决定）。
16、存储模式（内模式）与 SQL 的非过程性：存储模式（内模式）：数据在数据库中的内部表示，即对数据的物理结构和存储方式的描述。 综述：应用系统的全局关系模式对应于基本表，其存储结构对应于存储文件；面向用户的局部关系模式对应于视图或部分基本表。 SQL 包含对数据库的全部操作，用 SQL 语言可实现数据库应用过程中的全部活动。使用 SQL 只需指出需要哪类数据（做什么），不必指出获得这些数据的步骤（如何做）。
17、E-R 图的基本符号与联系类型：概念模型的建立方法是“实体-联系”方法，即 E-R 图。 在 E-R 图中，矩形表示实体，椭圆表示属性，菱形表示表与表之间的联系。 E-R 概念模型中存在一对一、一对多、多对多三种联系。
18、系统设计阶段的三级结构设计：“系统设计”阶段包括：概念结构设计（E-R 图）；逻辑结构设计（即关系模式设计）；物理结构设计（包含存储结构设计和程序结构设计）。
19、数据库控制与数据库保护：
1）数据库的破坏来自四个方面：系统故障、多用户并发访问数据库时造成数据的不一致、人为破坏、输入数据本身是错误的（或更新时造成数据错误）。
2）通过四个方面来实现数据库控制（即数据库保护）：安全性控制、备份与恢复、完整性控制、并发控制。
3）安全性控制：保护数据以防止不合法的使用。主要技术：
①用户标识与口令；
②访问控制（SQL 中的 GRANT 授权语句、REVOKE 取消授权语句用于访问授权）；
③审计；
④数据加密；
⑤视图的保护。 4）备份与恢复：实现技术是转储和日志。数据库恢复的基本机制就是“冗余”，通过备份来重复存储数据库中的数据。
考向复习提示：E-R 图三大核心图元与向关系模型转换规则
E-R 图三大图元：矩形表示实体集、椭圆形表示属性、菱形表示实体间的联系；联系度包含 1:1、1:n 和 m:n 三种；转换规则：一个 m:n 复合联系必须独立转换为一个单独的关系模式，其主键由两个相连实体的外键共同组成复合主键。
高频易错陷阱：E-R 图转关系模式高频丢分点
专转本大题必考：当两个实体集之间存在 1:n 关联（如班级与学生）时，必须将 1 端（班级）的主键作为外键添加到 n 端（学生表）中，而不是反过来把学生主键加到班级表中！如果加反会导致班级表出现多值属性破坏关系规范化；多对多联系若漏掉将其独立建表更是扣分雷区！$p0s_271$, $p0r_271${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S2-1.1 根据系统需求绘制 E-R 图。", "题库补充：数据库、DBMS 与 SQL 语言基础 (145题)", "题库补充：关系数据模型的三类完整性规则 (61题)", "题库补充：存储模式（内模式）与 SQL 的非过程性 (44题)", "题库补充：E-R 图的基本符号与联系类型 (40题)", "题库补充：系统设计阶段的三级结构设计 (35题)", "题库补充：数据库控制与数据库保护 (34题)", "p0_refine_20261113"], "pages": [60, 61, 62, 63, 64, 65], "spans": 78}$p0r_271$::jsonb, NOW());
