  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (293, 4, $p0b_293$[{"t": "list", "id": "s3-2-2-b1", "imp": "core", "items": ["1、基于用例分析建模过程（替换教学视频中过程描述）：", "（1）理解用例模型：理解用例模型和词汇表，适当补充系统内部情况的描述。", "（2）==识别分析类：找出可能的能够执行用例行为的分析类。==", "（3）定义交互行为：将用例行为分配到分析类中。", "（4）==建立分析类图：确定分析类关键属性和责任，定义分析类之间的关系。==", "（5）检查分析模型：", "①、检查“正确性”：用户是否理解相关术语表，描述的与用户下的定义是否一致等", "②、检查“完整性”：每个分析类是否都是用例需要，属性是何时被设置，类型是否符合实际情况等。", "③、检查“一致性”：类或用例是否重名，实体是否以同样的细节进行描述等", "④、检查“可行性”：是否可行，性能是否符合可靠性需求，是否在相关原型或硬件上进行验证。", "2、==分析类==", "（1）在分析模型中，分析类是概念层次上的内容，用于描述系统中较高层次的对象。", "（2）分析类直接与应用逻辑相关，而不关注于技术实现的问题。", "（3）==分析类的类型==：", "==①、实体类：表示系统存储和管理的永久信息。==", "==②、边界类：表示参与者与系统之间交互。==", "==③、控制类：表示系统在运行过程中的业务控制逻辑。==", "3、==实体类==", "（1）^^描述必须存储的信息及其相关行为^^。", "（2）^^通常对应现实世界中的“事物”。^^", "（3）==实体类与数据库的表对应，类的实例对应于表中的一条记录；类中的属性和记录中的字段对应。==", "（4）==实体类的UML 表示==："], "title": "", "ordered": false}, {"h": 254, "t": "img", "w": 520, "id": "s3-2-2-b2", "imp": "normal", "src": "/kb-assets/skill/p90_r0_6c1a6f2ca3839789.png", "title": ""}, {"t": "list", "id": "s3-2-2-b3", "imp": "core", "items": ["4、==边界类==", "（1）^^描述外部的参与者与系统之间的交互^^", "（2）类型：==用户界面、系统接口、设备接口==等", "（3）==边界类表示系统的用户界面，直接跟系统外部参与者交互，与系统进行信息交流。==如网上购物系统中登录子功能里的登录页面（login.html 或index.jsp）", "（4）==边界类的UML 表示==："], "title": "", "ordered": false}, {"h": 260, "t": "img", "w": 632, "id": "s3-2-2-b4", "imp": "normal", "src": "/kb-assets/skill/p91_r0_37b633ec1df94c14.png", "title": ""}, {"t": "list", "id": "s3-2-2-b5", "imp": "core", "items": ["5、==控制类==", "（1）^^描述一个用例所具有的事件流控制行为^^", "（2）^^实现对用例行为的封装，将用例的执行逻辑及边界和实体进行隔离^^", "（3）==控制类控制系统中对象之间的交互，通常每个用例对应一个控制类==", "（4）==控制类的UML 表示=="], "title": "", "ordered": false}, {"h": 229, "t": "img", "w": 632, "id": "s3-2-2-b6", "imp": "normal", "src": "/kb-assets/skill/p91_r1_6f1102534e6bf4ad.png", "title": ""}, {"t": "list", "id": "s3-2-2-b7", "imp": "important", "items": ["6、^^熟悉一下图中的各种类^^"], "title": "", "ordered": false}, {"h": 425, "t": "img", "w": 895, "id": "s3-2-2-b8", "imp": "normal", "src": "/kb-assets/skill/p91_r2_760ca439a32be7ac.png", "title": ""}, {"t": "list", "id": "s3-2-2-b9", "imp": "core", "items": ["7、==识别分析类==", "（1）==识别实体类==：", "①、==实体类通常是用例中的参与对象，对应着现实世界中的“事物”==", "②、^^事物列举^^："], "title": "", "ordered": false}, {"h": 515, "t": "img", "w": 1350, "id": "s3-2-2-b10", "imp": "normal", "src": "/kb-assets/skill/p91_r3_e1f58d85105d429c.png", "title": ""}, {"t": "list", "id": "s3-2-2-b11", "imp": "core", "items": ["③、识别实体类应当注意的问题实体类的识别质量在很大程度上取决于分析人员书写文档的风格和质量自然语言不是精确的，因此在分析自然语言描述时应该规范化描述文档中的一些措辞，尽量弥补这种不足；", "在自然语言描述中，名词可以对应类、属性或同义词等多种类型，开发人员需要花费大量时间进行筛选。", "（2）==识别边界类==", "①、==通常一个参与者与一个用例之间的交互或通信关联对应一个边界类==。", "②、列举："], "title": "", "ordered": false}, {"h": 270, "t": "img", "w": 679, "id": "s3-2-2-b12", "imp": "normal", "src": "/kb-assets/skill/p92_r0_4235bcd2f4195f1d.png", "title": ""}, {"t": "list", "id": "s3-2-2-b13", "imp": "core", "items": ["③、识别边界类应当注意的问题边界类应关注于参与者与用例之间交互的信息或响应的事件，不要描述窗口组件等界面的组成元素；", "在分析阶段，力求使用用户的术语描述界面边界类实例的生命周期并不仅限于用例的事件流,如果两个用例同时与一个参与者交互，那么它们有可能 会有共用一个边界类，以便增加边界类的复用性。", "（3）==识别控制类==", "①、==控制类负责协调边界类和实体类，通常在现实世界中没有对应的事物。==^^一般来说，一个用例对应一个控制类^^。", "②、列举："], "title": "", "ordered": false}, {"h": 224, "t": "img", "w": 661, "id": "s3-2-2-b14", "imp": "normal", "src": "/kb-assets/skill/p92_r1_a734c5662e970b87.png", "title": ""}, {"t": "list", "id": "s3-2-2-b15", "imp": "core", "items": ["③、识别控制类应当注意的问题当用例比较复杂时，特别是产生分支事件流的情况下，一个用例可以用多个控制类。", "在有些情况下，用例事件流的逻辑结构十分简单，@@这时没有必要使用控制类@@，边界类可以实现用例的行为。", "如果不同用例包含的任务之间存在着比较密切的联系，则这些用例可以使用一个控制类，其目的是复用相似部分以便降低复杂性。", "8、==建立分析类图==", "（1）==定义关系找出分析类之间的关系==。", "（2）==定义属性==", "^^①、按照一般常识，找出对象的某些属性；^^", "^^②、认真研究问题域，找出对象的某些属性；^^", "^^③、根据系统责任的要求，找出对象的某些属性；^^", "^^④、考虑对象需要系统保存的信息，找出对象的相应属性；^^", "^^⑤、对象为了服务中实现其功能，需要增设一些属性；^^", "^^⑥、识别对象需要区别的状态，考虑是否需要增加一个属性来区别这些状态^^", "^^⑦、确定属性表示整体及部分结构和实例连接。^^", "9、==类之间关系=="], "title": "", "ordered": false}, {"h": 578, "t": "img", "w": 975, "id": "s3-2-2-b16", "imp": "normal", "src": "/kb-assets/skill/p93_r0_f24269249027d285.png", "title": ""}, {"t": "list", "id": "s3-2-2-b17", "imp": "core", "items": ["（1）==继承（泛化）关系==", "①、==是一种继承关系，表示一般与特殊的关系，它指定了子类如何特化父类的所有特征和行为。继承是类与类或者接口与接口之间最常见的关系；==", "②、==UML 表示：带三角箭头的实线，箭头指向父类。==", "③、实例：老虎与动物的关系"], "title": "", "ordered": false}, {"t": "img", "id": "s3-2-2-rel-card-1", "imp": "normal", "src": "/kb-assets/refinement/s322-rel-generalization.png", "w": 1720, "h": 580, "alt": "UML 继承（泛化）关系图元与 Animal/Tiger 类图实例", "title": "", "caption": "（1）继承（泛化）关系 UML 图元及 Tiger → Animal 教材实例（实线+空心三角）"}, {"t": "list", "id": "s3-2-2-b21", "imp": "core", "items": ["（2）==实现关系==", "①、==是一种类与接口的关系，表示类是接口所有特征和行为的实现. 一个class 类实现interface 接口（可以是多个）的功能；实现是类与接口之间最常见的关系；==", "②、==UML 表示：带空心三角箭头的虚线，箭头指向接口（被实现的类）。==", "③、实例：画笔实现画"], "title": "", "ordered": false}, {"t": "img", "id": "s3-2-2-rel-card-2", "imp": "normal", "src": "/kb-assets/refinement/s322-rel-realization.png", "w": 1720, "h": 580, "alt": "UML 实现关系图元与 PenBrush/IBrush 接口类图实例", "title": "", "caption": "（2）实现关系 UML 图元及 PenBrush ⇢ IBrush 教材实例（虚线+空心三角）"}, {"t": "list", "id": "s3-2-2-b25", "imp": "core", "items": ["（3）==依赖关系==", "①、==是一种使用的关系，即一个类的实现需要另一个类的协助，所以要尽量不使用双向的互相依赖.== 一个类A 使用到了另一个类B，：而这种使用关系是具有偶然性的、临时性的、非常弱的，但是B 类的变化会影响到A；比如某个老师要授课，则需要有这么一门课让他教授，此时老师与课之间的关系就是依赖；", "②、==UML 表示：带箭头的虚线，指向被使用者==。", "③、实例：现代人与计算机"], "title": "", "ordered": false}, {"t": "img", "id": "s3-2-2-rel-card-3", "imp": "normal", "src": "/kb-assets/refinement/s322-rel-dependency.png", "w": 1720, "h": 580, "alt": "UML 依赖关系图元与现代人/计算机类图实例", "title": "", "caption": "（3）依赖关系 UML 图元及 现代人 ⇢ 计算机 教材实例（虚线+普通箭头，已订正简体）"}, {"t": "list", "id": "s3-2-2-b29", "imp": "core", "items": ["（4）==关联关系==", "①、==是类与类之间的联接，它使一个类知道另一个类的属性和方法。==两个类或者类与接口之间语义级别的一种强依赖关系，这种关系比依赖更强，一般是长期性的，而且双方的关系一般是平等的。比如：老师与学生，丈夫与妻子关联可以是双向的，也可以是单向的。==双向的关联可以有两个箭头或者没有箭头，单向的关联有一个箭头==。", "②、==UML 表示：带普通箭头的实心线，指向被拥有者==。", "③、实例： 单身汉自己；老师、学生和课程三者之间"], "title": "", "ordered": false}, {"t": "img", "id": "s3-2-2-rel-card-4", "imp": "normal", "src": "/kb-assets/refinement/s322-rel-association.png", "w": 2040, "h": 620, "alt": "UML 关联关系图元与单身汉自关联及老师-学生-课程类图实例", "title": "", "caption": "（4）关联关系 UML 图元及自关联、n:n 双向与 1:n 单向关联教材实例"}, {"t": "list", "id": "s3-2-2-b33", "imp": "core", "items": ["（5）==聚合关系==", "①、==是关联关系的一种特例, 是强的关联关系.== 聚合是整体与部分的关系，且部分可以离开整体而单独存在，他们可以具有各自的生命周期，部分可以属于多个整体对象，也可以为多个整体对象共享，比如计算机与CPU、公司与员工、车和轮胎的关系等；表现在代码层面，和关联关系是一致的，只能从语义级别来区分；", "②、==UML 表示：带空心菱形的实心线，菱形指向整体==", "③、实例：汽车与引擎和轮胎"], "title": "", "ordered": false}, {"t": "img", "id": "s3-2-2-rel-card-5", "imp": "normal", "src": "/kb-assets/refinement/s322-rel-aggregation.png", "w": 1720, "h": 720, "alt": "UML 聚合关系图元与汽车-引擎-轮胎类图实例", "title": "", "caption": "（5）聚合关系 UML 图元及 汽车(1) ◇→ 引擎(1)/轮胎(4) 教材实例（空心菱形在整体端）"}, {"t": "list", "id": "s3-2-2-b37", "imp": "core", "items": ["（6）==组合关系==", "①、==也是关联关系的一种特例，是比聚合关系还要强的关系，也称为强聚合==；他同样体现整体与部分间的关系，但此时整体与部分是不可分的，整体的生命周期结束也就意味着部分的生命周期结束；比如：", "公司和部门是整体和部分的关系，没有公司就不存在部门；@@组合（合成）关系中的部分不可被多个整体共享@@。", "②、==UML 表示：带实心菱形的实线，菱形指向整体==", "③、实例：公司与部门之间关系"], "title": "", "ordered": false}, {"t": "img", "id": "s3-2-2-rel-card-6", "imp": "normal", "src": "/kb-assets/refinement/s322-rel-composition.png", "w": 1720, "h": 580, "alt": "UML 组合关系图元与公司-部门类图实例", "title": "", "caption": "（6）组合关系 UML 图元及 公司(1) ◆→ 部门(n) 教材实例（实心菱形在整体端）"}, {"t": "list", "id": "s3-2-2-b41", "imp": "core", "items": ["10、==画类图==", "（1）==根据识别出来的类，相关类定义的相关属性及行为（方法），以类之间的关系进行绘制==。", "（2）实例："], "title": "", "ordered": false}, {"h": 815, "t": "img", "w": 1000, "id": "s3-2-2-b42", "imp": "normal", "src": "/kb-assets/skill/p96_r0_a7700863a02ccccf.png", "title": ""}, {"t": "callout", "id": "s3-2-2-b43", "imp": "core", "kind": "tip", "text": "• ==泛化（Generalization，继承）==：实线 + 空心三角形箭头（子类指向父类）； • ==实现（Realization）==：虚线 + 空心三角形箭头（类指向接口）； • ==关联（Association）==：实线连线（强长期联系，包含多重度如 `0..*`）； • ==依赖（Dependency）==：虚线带普通箭头（弱临时联系，如局部变量、参数传递）。", "title": "考向复习提示：类与类之间四大核心关系图元与连线"}, {"t": "callout", "id": "s3-2-2-b44", "imp": "core", "kind": "trap", "text": "专转本真题必考高级关联辨析： • ==聚合关系（Aggregation，空心菱形）：表示“弱拥有的 has-a 关系”==（如：大学与学生），学生离开大学依然可以独立存在，部分脱离整体仍能存活； • ==组合关系（Composition，实心菱形）：表示“强同生共死的 contains-a 关系”==（如：公司与部门、鸟与翅膀），整体一旦毁灭，部分随之瞬间毁灭，生命周期完全同步！", "title": "高频易错陷阱：聚合关系与组合关系在生命周期上的生死绑定差异"}]$p0b_293$::jsonb, '', $p0s_293$1、基于用例分析建模过程（替换教学视频中过程描述）：
（1）理解用例模型：理解用例模型和词汇表，适当补充系统内部情况的描述。
（2）识别分析类：找出可能的能够执行用例行为的分析类。
（3）定义交互行为：将用例行为分配到分析类中。
（4）建立分析类图：确定分析类关键属性和责任，定义分析类之间的关系。
（5）检查分析模型：
①、检查“正确性”：用户是否理解相关术语表，描述的与用户下的定义是否一致等
②、检查“完整性”：每个分析类是否都是用例需要，属性是何时被设置，类型是否符合实际情况等。
③、检查“一致性”：类或用例是否重名，实体是否以同样的细节进行描述等
④、检查“可行性”：是否可行，性能是否符合可靠性需求，是否在相关原型或硬件上进行验证。
2、分析类
（1）在分析模型中，分析类是概念层次上的内容，用于描述系统中较高层次的对象。
（2）分析类直接与应用逻辑相关，而不关注于技术实现的问题。
（3）分析类的类型：
①、实体类：表示系统存储和管理的永久信息。
②、边界类：表示参与者与系统之间交互。
③、控制类：表示系统在运行过程中的业务控制逻辑。
3、实体类
（1）描述必须存储的信息及其相关行为。
（2）通常对应现实世界中的“事物”。
（3）实体类与数据库的表对应，类的实例对应于表中的一条记录；类中的属性和记录中的字段对应。
（4）实体类的UML 表示：
4、边界类
（1）描述外部的参与者与系统之间的交互
（2）类型：用户界面、系统接口、设备接口等
（3）边界类表示系统的用户界面，直接跟系统外部参与者交互，与系统进行信息交流。如网上购物系统中登录子功能里的登录页面（login.html 或index.jsp）
（4）边界类的UML 表示：
5、控制类
（1）描述一个用例所具有的事件流控制行为
（2）实现对用例行为的封装，将用例的执行逻辑及边界和实体进行隔离
（3）控制类控制系统中对象之间的交互，通常每个用例对应一个控制类
（4）控制类的UML 表示
6、熟悉一下图中的各种类
7、识别分析类
（1）识别实体类：
①、实体类通常是用例中的参与对象，对应着现实世界中的“事物”
②、事物列举：
③、识别实体类应当注意的问题实体类的识别质量在很大程度上取决于分析人员书写文档的风格和质量自然语言不是精确的，因此在分析自然语言描述时应该规范化描述文档中的一些措辞，尽量弥补这种不足；
在自然语言描述中，名词可以对应类、属性或同义词等多种类型，开发人员需要花费大量时间进行筛选。
（2）识别边界类
①、通常一个参与者与一个用例之间的交互或通信关联对应一个边界类。
②、列举：
③、识别边界类应当注意的问题边界类应关注于参与者与用例之间交互的信息或响应的事件，不要描述窗口组件等界面的组成元素；
在分析阶段，力求使用用户的术语描述界面边界类实例的生命周期并不仅限于用例的事件流,如果两个用例同时与一个参与者交互，那么它们有可能 会有共用一个边界类，以便增加边界类的复用性。
（3）识别控制类
①、控制类负责协调边界类和实体类，通常在现实世界中没有对应的事物。一般来说，一个用例对应一个控制类。
②、列举：
③、识别控制类应当注意的问题当用例比较复杂时，特别是产生分支事件流的情况下，一个用例可以用多个控制类。
在有些情况下，用例事件流的逻辑结构十分简单，这时没有必要使用控制类，边界类可以实现用例的行为。
如果不同用例包含的任务之间存在着比较密切的联系，则这些用例可以使用一个控制类，其目的是复用相似部分以便降低复杂性。
8、建立分析类图
（1）定义关系找出分析类之间的关系。
（2）定义属性
①、按照一般常识，找出对象的某些属性；
②、认真研究问题域，找出对象的某些属性；
③、根据系统责任的要求，找出对象的某些属性；
④、考虑对象需要系统保存的信息，找出对象的相应属性；
⑤、对象为了服务中实现其功能，需要增设一些属性；
⑥、识别对象需要区别的状态，考虑是否需要增加一个属性来区别这些状态
⑦、确定属性表示整体及部分结构和实例连接。
9、类之间关系
（1）继承（泛化）关系
①、是一种继承关系，表示一般与特殊的关系，它指定了子类如何特化父类的所有特征和行为。继承是类与类或者接口与接口之间最常见的关系；
②、UML 表示：带三角箭头的实线，箭头指向父类。
③、实例：老虎与动物的关系
（1）继承（泛化）关系 UML 图元及 Tiger → Animal 教材实例（实线+空心三角）
UML 继承（泛化）关系图元与 Animal/Tiger 类图实例
（2）实现关系
①、是一种类与接口的关系，表示类是接口所有特征和行为的实现. 一个class 类实现interface 接口（可以是多个）的功能；实现是类与接口之间最常见的关系；
②、UML 表示：带空心三角箭头的虚线，箭头指向接口（被实现的类）。
③、实例：画笔实现画
（2）实现关系 UML 图元及 PenBrush ⇢ IBrush 教材实例（虚线+空心三角）
UML 实现关系图元与 PenBrush/IBrush 接口类图实例
（3）依赖关系
①、是一种使用的关系，即一个类的实现需要另一个类的协助，所以要尽量不使用双向的互相依赖. 一个类A 使用到了另一个类B，：而这种使用关系是具有偶然性的、临时性的、非常弱的，但是B 类的变化会影响到A；比如某个老师要授课，则需要有这么一门课让他教授，此时老师与课之间的关系就是依赖；
②、UML 表示：带箭头的虚线，指向被使用者。
③、实例：现代人与计算机
（3）依赖关系 UML 图元及 现代人 ⇢ 计算机 教材实例（虚线+普通箭头，已订正简体）
UML 依赖关系图元与现代人/计算机类图实例
（4）关联关系
①、是类与类之间的联接，它使一个类知道另一个类的属性和方法。两个类或者类与接口之间语义级别的一种强依赖关系，这种关系比依赖更强，一般是长期性的，而且双方的关系一般是平等的。比如：老师与学生，丈夫与妻子关联可以是双向的，也可以是单向的。双向的关联可以有两个箭头或者没有箭头，单向的关联有一个箭头。
②、UML 表示：带普通箭头的实心线，指向被拥有者。
③、实例： 单身汉自己；老师、学生和课程三者之间
（4）关联关系 UML 图元及自关联、n:n 双向与 1:n 单向关联教材实例
UML 关联关系图元与单身汉自关联及老师-学生-课程类图实例
（5）聚合关系
①、是关联关系的一种特例, 是强的关联关系. 聚合是整体与部分的关系，且部分可以离开整体而单独存在，他们可以具有各自的生命周期，部分可以属于多个整体对象，也可以为多个整体对象共享，比如计算机与CPU、公司与员工、车和轮胎的关系等；表现在代码层面，和关联关系是一致的，只能从语义级别来区分；
②、UML 表示：带空心菱形的实心线，菱形指向整体
③、实例：汽车与引擎和轮胎
（5）聚合关系 UML 图元及 汽车(1) ◇→ 引擎(1)/轮胎(4) 教材实例（空心菱形在整体端）
UML 聚合关系图元与汽车-引擎-轮胎类图实例
（6）组合关系
①、也是关联关系的一种特例，是比聚合关系还要强的关系，也称为强聚合；他同样体现整体与部分间的关系，但此时整体与部分是不可分的，整体的生命周期结束也就意味着部分的生命周期结束；比如：
公司和部门是整体和部分的关系，没有公司就不存在部门；组合（合成）关系中的部分不可被多个整体共享。
②、UML 表示：带实心菱形的实线，菱形指向整体
③、实例：公司与部门之间关系
（6）组合关系 UML 图元及 公司(1) ◆→ 部门(n) 教材实例（实心菱形在整体端）
UML 组合关系图元与公司-部门类图实例
10、画类图
（1）根据识别出来的类，相关类定义的相关属性及行为（方法），以类之间的关系进行绘制。
（2）实例：
考向复习提示：类与类之间四大核心关系图元与连线
• 泛化（Generalization，继承）：实线 + 空心三角形箭头（子类指向父类）； • 实现（Realization）：虚线 + 空心三角形箭头（类指向接口）； • 关联（Association）：实线连线（强长期联系，包含多重度如 0..*）； • 依赖（Dependency）：虚线带普通箭头（弱临时联系，如局部变量、参数传递）。
高频易错陷阱：聚合关系与组合关系在生命周期上的生死绑定差异
专转本真题必考高级关联辨析： • 聚合关系（Aggregation，空心菱形）：表示“弱拥有的 has-a 关系”（如：大学与学生），学生离开大学依然可以独立存在，部分脱离整体仍能存活； • 组合关系（Composition，实心菱形）：表示“强同生共死的 contains-a 关系”（如：公司与部门、鸟与翅膀），整体一旦毁灭，部分随之瞬间毁灭，生命周期完全同步！$p0s_293$, $p0r_293${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S3-2.2 分析识别类，绘制类图。", "2024校验清理：修正实现关系UML图例错配(实线->虚线指向接口)、这时没有必要反义词及多处错别字", "p0_refine_20261113"], "pages": [90, 91, 92, 93, 94, 95, 96], "spans": 70}$p0r_293$::jsonb, NOW());
