  VALUES (294, 3, $p0b_294$[{"t": "list", "id": "s3-2-3-b1", "imp": "core", "items": ["1、==对象图==", "（1）==对象图(Object Diagram) 是显示了一组对象和他们之间的关系==。", "（2）==使用对象图来说明数据结构，类图中的类或组件等的实例的静态快照==。", "2、画法：", "==对象名：类名==", "3、实例："], "title": "", "ordered": false}, {"h": 658, "t": "img", "w": 823, "id": "s3-2-3-b2", "imp": "normal", "src": "/kb-assets/skill/p96_r1_fd87e674076e3d89.png", "title": ""}, {"t": "callout", "id": "s3-2-3-b3", "imp": "normal", "kind": "tip", "text": "对象图是类图的一个实例在某一特定时刻的物理快照（Snapshot）；用于在系统运行期直观验证复杂类图结构设计的正确性；对象节点中属性包含具体的实际运行期取值数值；关系仅展示对象之间的物理链接（Link）。", "title": "考向复习提示：对象图（Object Diagram）的快照本质"}, {"t": "callout", "id": "s3-2-3-b4", "imp": "core", "kind": "trap", "text": "在 UML 语法标准中，对象图节点第一行的书写格式必须是：`对象名: 类名`；==其最关键的语法标识是：整个字符串下方必须带有“单下划线”（如 `<u>zhangSan: Student</u>`）==！没有下划线会被误判为类节点！匿名对象可简写为 `: 类名`（同样必须带下划线）！", "title": "高频易错陷阱：对象图节点的名称下划线强制规范"}]$p0b_294$::jsonb, '', $p0s_294$1、对象图
（1）对象图(Object Diagram) 是显示了一组对象和他们之间的关系。
（2）使用对象图来说明数据结构，类图中的类或组件等的实例的静态快照。
2、画法：
对象名：类名
3、实例：
考向复习提示：对象图（Object Diagram）的快照本质
对象图是类图的一个实例在某一特定时刻的物理快照（Snapshot）；用于在系统运行期直观验证复杂类图结构设计的正确性；对象节点中属性包含具体的实际运行期取值数值；关系仅展示对象之间的物理链接（Link）。
高频易错陷阱：对象图节点的名称下划线强制规范
在 UML 语法标准中，对象图节点第一行的书写格式必须是：对象名: 类名；其最关键的语法标识是：整个字符串下方必须带有“单下划线”（如 <u>zhangSan: Student</u>）！没有下划线会被误判为类节点！匿名对象可简写为 : 类名（同样必须带下划线）！$p0s_294$, $p0r_294${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S3-2.3 绘制对象图。", "p0_refine_20261113"], "pages": [96, 97], "spans": 5}$p0r_294$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 3, updated_at = NOW() WHERE node_id = 294;
END $$;

