  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (309, 3, $p0b_309$[{"t": "list", "id": "s4-2-2-b1", "imp": "core", "items": ["1、==配置无线局域网的 SSID==", "（1）==SSID 是Service Set Identifier 的缩写，意思是：服务集标识。==", "（2）==SSID 技术可以将一个无线局域网分为几个需要不同身份验证的子网络，每一个子网络都需要独立的身份验证，只有通过身份验证的用户才可以进入相应的子网络，防止未被授权的用户进入本网络。==", "（3）SSID 是个笼统的概念，包含了ESSID 和BSSID，用来区分不同的网络，@@最多可以有32 个字符(数字、字母等，有些设备支持中文)@@，无线网卡设置了不同的SSID 就可以进入不同网络，SSID 通常由AP 广播出来，通过XP（各操作系统都有）自带的扫描功能可以查看当前区域内的SSID。", "（4）==出于安全考虑可以不广播SSID，此时用户就要手工设置SSID 才能进入相应的网络。==", "（5）简单说，==SSID 就是一个局域网的名称，只有设置为名称相同SSID 的值的电脑才能互相通信。==", "（6）举例："], "title": "", "ordered": false}, {"h": 263, "t": "img", "w": 507, "id": "s4-2-2-b2", "imp": "normal", "src": "/kb-assets/skill/p116_r0_f839435523f9c38d.png", "title": ""}, {"t": "list", "id": "s4-2-2-b3", "imp": "core", "items": ["2、==配置安全类型和加密类型==", "（1）常见的安全类型和加密类型：==无身份验证（开放式）、共享式（WEP）、WPA、802.1X==", "（2）==无身份验证（开放式）==：", "==①、早期的 WiFi 没有提供数据加密，即无身份认证的开放式无线网络，任何设备不需要授权即可连接到该网络。==", "==②、连接到这样的无线网络后系统里的无线连接会提示“不安全”，因为通过这样的 WiFi 进行连接很容易遭到窃听。=="], "title": "", "ordered": false}, {"h": 252, "t": "img", "w": 495, "id": "s4-2-2-b4", "imp": "normal", "src": "/kb-assets/skill/p116_r1_acd2fc92aac7b015.png", "title": ""}, {"t": "list", "id": "s4-2-2-b5", "imp": "core", "items": ["（3）==共享式（WEP）==", "①、==WEP== 即 Wired Equivalent Privacy 的缩写，表示==有线等效保密==。", "②、1999 年，WEP 加密协议获得通过，提供了与有线连接等效的加密安全性。然而后来事实证明 @@WEP很容易遭到破解@@，于是 WPA 加密方式应运而生。所以，@@有更高加密标准可用的时候，一般不使用 WEP加密类型。@@"], "title": "", "ordered": false}, {"h": 251, "t": "img", "w": 582, "id": "s4-2-2-b6", "imp": "normal", "src": "/kb-assets/skill/p116_r2_7818c64e76713d45.png", "title": ""}, {"t": "list", "id": "s4-2-2-b7", "imp": "core", "items": ["（4）==WPA==", "①、==WPA2 -个人、WPA – 个人、WPA2 – 企业、WPA – 企业这四种安全类型都属于 WPA==，==WPA2 是WPA 的升级版。WPA3== 标准包括==个人==、==企业==两种模式，同时还可以应用于物联网领域。", "②、==WPA 的设计可以用在所有的无线网卡上，但不一定能用在第一代的无线热点（比如无线路由器）上。WPA2 可能不能用在某些旧型号的网卡上。==", "③、==WPA 和 WPA2 都采用 TKIP（本质是WEP 补丁） 或者 AES（对称，高级加密标准） 加密方式，比 WEP 的加密级别高，因而更安全。==", "④、==AES 是一个完全独立的加密算法==，远远优于任何TKIP 提供的算法，该算法有==128 位，192 位或256位的分组密码==。所以==AES 安全性能比TKIP 好==。", "⑤、==AES 加密方式时，密码（网络安全密钥）长度要求为 8~63 个 ASCII 字符或 8-64 个十六进制字符（简单讲就是可以设置 8~64 个字母、数字和英文标点符号的字符组合作为密码）==。", "⑥、企业版需要有专用的服务器来发放和验证证书，不使用密码；", "⑦、个人版则不需要专用的证书，可以使用预先设定的密码（预共享密钥，pre-shared key，缩写PSK）。所以很多地方又将 @@WPA – 个人或者 WPA2 – 个人称为 WPA -PSK 和 WPA2 – PSK@@。", "⑧、==WPA3 是新近发布的WIFI 安全标准==，提供更加安全的私有和公共网络。==WPA3== 标准包括==个人、企业==两种模式。@@WPA3 加密是在256 位伽罗瓦/计数器模式协议(GCMP-256)覆盖之下，因此使得破解加密的难度更大。@@"], "title": "", "ordered": false}, {"h": 308, "t": "img", "w": 602, "id": "s4-2-2-b8", "imp": "normal", "src": "/kb-assets/skill/p117_r0_2b6b64e7b9854e9f.png", "title": ""}, {"t": "list", "id": "s4-2-2-b9", "imp": "core", "items": ["（5）==802.1X==", "①、==802.1x 协议是基于Client/Server 的访问控制和认证协议。==", "②、==类似于企业版的 WPA，802.1X 也需要专门的认证服务器来对 WiFi 连接进行认证。==", "③、==它可以限制未经授权的用户/设备通过接入端口(access port)访问LAN/WLAN==。", "④、在获得交换机或LAN 提供的各种业务之前，802.1x 对连接到交换机端口上的用户/设备进行认证。", "⑤、在认证通过之前，802.1x 只允许EAPOL（基于局域网的扩展认证协议）数据通过设备连接的交换机端口；认证通过以后，正常的数据可以顺利地通过以太网端口。"], "title": "", "ordered": false}, {"h": 331, "t": "img", "w": 406, "id": "s4-2-2-b10", "imp": "normal", "src": "/kb-assets/skill/p117_r1_087b7d127414f841.png", "title": ""}, {"t": "list", "id": "s4-2-2-b11", "imp": "core", "items": ["3、==连接WIFI 配置（Windows  10 笔记本连WIFI）==", "（1）第一种：==网络和Internet 中WLAN 配置管理已知网络进行增加新网络连接信息（SSID、安全类型、安全密码等）==。", "（2）第二种：==直接搜索的WIFI 网络进行输入密码连接=="], "title": "", "ordered": false}, {"h": 479, "t": "img", "w": 1218, "id": "s4-2-2-b12", "imp": "normal", "src": "/kb-assets/skill/p118_r0_4be8069a9142bc42.png", "title": ""}, {"t": "list", "id": "s4-2-2-b13", "imp": "core", "items": ["第一种                                             第二种", "4、==无线路由器设置多 SSID==：==家庭和中小企业无线网络常用的设备是无线路由器==，它集中了无线 AP 与宽带路由器的功能。使用无线路由器，移动用户可以通过拥有无线网卡的设备连入无线网络，实现移动互通。无线路由器有一个比较特殊的功能称为多 SSID，可以迅速让一台无线路由器变成两台甚至更多台。", "5、==无线路由器的信息安全==：^^避免他人蹭网^^：==启用身份认证==，使用有一定强度的口令（密码）；关闭 SSID 广播；使用 MAC 地址过滤限制他人连接。 增强数据通信安全：WEP 加密、WPA 加密、WPA2 加密；个人模式（WPA-PSK / WPA2-PSK）与企业模式（WPA / WPA2）。 同时应修改路由器的默认管理口令。", "6、^^配置无线安全类型与加密方式^^：", "1、无线网卡 Authentication 设置中可选 Disabled、WEP、WPA-PSK、WPA2-PSK、WPA、WPA2。选择 WPA2-PSK 时需填写 PSK 密码（如 123456789），加密类型选 AES；选择 WPA/WPA2 企业模式时需填写 RADIUS 服务器的 IP 地址与共享密钥。"], "title": "", "ordered": false}, {"t": "callout", "id": "s4-2-2-b14", "imp": "core", "kind": "tip", "text": "无线局域网标准配置： 1. ==SSID（服务集标识符，即用户搜索连接时看到的 Wi-Fi 名字，支持隐藏广播）==； 2. 安全加密模式：==WPA2-PSK / WPA3-SAE（目前最安全的个人预共享密钥模式，采用 AES/CCMP 高强度对称加密）==； 3. 工作频段：2.4 GHz（穿墙强抗衰减、干扰多）与 5 GHz（带宽大速度极快、穿墙衰减大）。", "title": "考向复习提示：Wi-Fi 核心配置三要素（SSID、加密认证、信道）"}, {"t": "callout", "id": "s4-2-2-b15", "imp": "core", "kind": "trap", "text": "专转本网络安全选择题常考：==WEP（有线等效保密协议）采用 RC4 流密码体制，存在严重的伪随机弱密钥漏洞，黑客在局域网内只需监听抓取数万个数据包即可在数分钟内完全暴力破解出 Wi-Fi 密码==！因此在新大纲安全标准中，WEP 已经被彻底淘汰并明令禁止使用，必须选择 WPA2 或 WPA3！", "title": "高频易错陷阱：早期的 WEP 加密存在致命数学漏洞，严禁使用！"}]$p0b_309$::jsonb, '', $p0s_309$1、配置无线局域网的 SSID
（1）SSID 是Service Set Identifier 的缩写，意思是：服务集标识。
（2）SSID 技术可以将一个无线局域网分为几个需要不同身份验证的子网络，每一个子网络都需要独立的身份验证，只有通过身份验证的用户才可以进入相应的子网络，防止未被授权的用户进入本网络。
（3）SSID 是个笼统的概念，包含了ESSID 和BSSID，用来区分不同的网络，最多可以有32 个字符(数字、字母等，有些设备支持中文)，无线网卡设置了不同的SSID 就可以进入不同网络，SSID 通常由AP 广播出来，通过XP（各操作系统都有）自带的扫描功能可以查看当前区域内的SSID。
（4）出于安全考虑可以不广播SSID，此时用户就要手工设置SSID 才能进入相应的网络。
（5）简单说，SSID 就是一个局域网的名称，只有设置为名称相同SSID 的值的电脑才能互相通信。
（6）举例：
2、配置安全类型和加密类型
（1）常见的安全类型和加密类型：无身份验证（开放式）、共享式（WEP）、WPA、802.1X
（2）无身份验证（开放式）：
①、早期的 WiFi 没有提供数据加密，即无身份认证的开放式无线网络，任何设备不需要授权即可连接到该网络。
②、连接到这样的无线网络后系统里的无线连接会提示“不安全”，因为通过这样的 WiFi 进行连接很容易遭到窃听。
（3）共享式（WEP）
①、WEP 即 Wired Equivalent Privacy 的缩写，表示有线等效保密。
②、1999 年，WEP 加密协议获得通过，提供了与有线连接等效的加密安全性。然而后来事实证明 WEP很容易遭到破解，于是 WPA 加密方式应运而生。所以，有更高加密标准可用的时候，一般不使用 WEP加密类型。
（4）WPA
①、WPA2 -个人、WPA – 个人、WPA2 – 企业、WPA – 企业这四种安全类型都属于 WPA，WPA2 是WPA 的升级版。WPA3 标准包括个人、企业两种模式，同时还可以应用于物联网领域。
②、WPA 的设计可以用在所有的无线网卡上，但不一定能用在第一代的无线热点（比如无线路由器）上。WPA2 可能不能用在某些旧型号的网卡上。
③、WPA 和 WPA2 都采用 TKIP（本质是WEP 补丁） 或者 AES（对称，高级加密标准） 加密方式，比 WEP 的加密级别高，因而更安全。
④、AES 是一个完全独立的加密算法，远远优于任何TKIP 提供的算法，该算法有128 位，192 位或256位的分组密码。所以AES 安全性能比TKIP 好。
⑤、AES 加密方式时，密码（网络安全密钥）长度要求为 8~63 个 ASCII 字符或 8-64 个十六进制字符（简单讲就是可以设置 8~64 个字母、数字和英文标点符号的字符组合作为密码）。
⑥、企业版需要有专用的服务器来发放和验证证书，不使用密码；
⑦、个人版则不需要专用的证书，可以使用预先设定的密码（预共享密钥，pre-shared key，缩写PSK）。所以很多地方又将 WPA – 个人或者 WPA2 – 个人称为 WPA -PSK 和 WPA2 – PSK。
⑧、WPA3 是新近发布的WIFI 安全标准，提供更加安全的私有和公共网络。WPA3 标准包括个人、企业两种模式。WPA3 加密是在256 位伽罗瓦/计数器模式协议(GCMP-256)覆盖之下，因此使得破解加密的难度更大。
（5）802.1X
①、802.1x 协议是基于Client/Server 的访问控制和认证协议。
②、类似于企业版的 WPA，802.1X 也需要专门的认证服务器来对 WiFi 连接进行认证。
③、它可以限制未经授权的用户/设备通过接入端口(access port)访问LAN/WLAN。
④、在获得交换机或LAN 提供的各种业务之前，802.1x 对连接到交换机端口上的用户/设备进行认证。
⑤、在认证通过之前，802.1x 只允许EAPOL（基于局域网的扩展认证协议）数据通过设备连接的交换机端口；认证通过以后，正常的数据可以顺利地通过以太网端口。
3、连接WIFI 配置（Windows 10 笔记本连WIFI）
（1）第一种：网络和Internet 中WLAN 配置管理已知网络进行增加新网络连接信息（SSID、安全类型、安全密码等）。
（2）第二种：直接搜索的WIFI 网络进行输入密码连接
第一种 第二种
4、无线路由器设置多 SSID：家庭和中小企业无线网络常用的设备是无线路由器，它集中了无线 AP 与宽带路由器的功能。使用无线路由器，移动用户可以通过拥有无线网卡的设备连入无线网络，实现移动互通。无线路由器有一个比较特殊的功能称为多 SSID，可以迅速让一台无线路由器变成两台甚至更多台。
5、无线路由器的信息安全：避免他人蹭网：启用身份认证，使用有一定强度的口令（密码）；关闭 SSID 广播；使用 MAC 地址过滤限制他人连接。 增强数据通信安全：WEP 加密、WPA 加密、WPA2 加密；个人模式（WPA-PSK / WPA2-PSK）与企业模式（WPA / WPA2）。 同时应修改路由器的默认管理口令。
6、配置无线安全类型与加密方式：
1、无线网卡 Authentication 设置中可选 Disabled、WEP、WPA-PSK、WPA2-PSK、WPA、WPA2。选择 WPA2-PSK 时需填写 PSK 密码（如 123456789），加密类型选 AES；选择 WPA/WPA2 企业模式时需填写 RADIUS 服务器的 IP 地址与共享密钥。
考向复习提示：Wi-Fi 核心配置三要素（SSID、加密认证、信道）
无线局域网标准配置： 1. SSID（服务集标识符，即用户搜索连接时看到的 Wi-Fi 名字，支持隐藏广播）； 2. 安全加密模式：WPA2-PSK / WPA3-SAE（目前最安全的个人预共享密钥模式，采用 AES/CCMP 高强度对称加密）； 3. 工作频段：2.4 GHz（穿墙强抗衰减、干扰多）与 5 GHz（带宽大速度极快、穿墙衰减大）。
高频易错陷阱：早期的 WEP 加密存在致命数学漏洞，严禁使用！
专转本网络安全选择题常考：WEP（有线等效保密协议）采用 RC4 流密码体制，存在严重的伪随机弱密钥漏洞，黑客在局域网内只需监听抓取数万个数据包即可在数分钟内完全暴力破解出 Wi-Fi 密码！因此在新大纲安全标准中，WEP 已经被彻底淘汰并明令禁止使用，必须选择 WPA2 或 WPA3！$p0s_309$, $p0r_309${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S4-2.2 配置无线局域网的 SSID、安全类型和加密类型。", "题库补充：无线路由器设置多 SSID (24题)", "题库补充：无线路由器的信息安全 (17题)", "题库补充：配置无线安全类型与加密方式 (5题)", "p0_refine_20261113"], "pages": [116, 117, 118], "spans": 49}$p0r_309$::jsonb, NOW());
