  VALUES (313, 4, $p0b_313$[{"t": "list", "id": "s5-1-2-b1", "imp": "core", "items": ["==1、软件=程序+数据+相关文档。==", "==2、软件（应用程序）对应有32 位或64 位之分。==", "==3、在32 位和64 位操作系统中安装应用程序时存在的区别=="], "title": "", "ordered": false}, {"h": 420, "t": "img", "w": 1317, "id": "s5-1-2-b2", "imp": "normal", "src": "/kb-assets/skill/p122_r0_c6d63b1231611c94.png", "title": ""}, {"t": "list", "id": "s5-1-2-b3", "imp": "core", "items": ["1、安装应用程序的实际过程通常并不复杂，而且大多数应用程序都通过安装向导将其安装到系统中。以下==通用流程==：", "（1）==启动安装用户程序==：安装文件的名称通常为“Setup.exe”或“Install.exe”", "（2）==运行程序安装向导==：运行安装向导之前，会检测安装程序所需的用户权限。一般需要管理员访权限，可能会需要同意安装协议等才能继续进行安装。", "（3）==选择安装方式==：默认安装和自定义安装。", "（4）==完成安装==：按向导指引操作后，最终完成安装。有些程序安装之后需要重启计算机。"], "title": "", "ordered": false}, {"h": 464, "t": "img", "w": 1281, "id": "s5-1-2-b4", "imp": "normal", "src": "/kb-assets/skill/p122_r1_df38016b9c9c6825.png", "title": ""}, {"t": "list", "id": "s5-1-2-b5", "imp": "core", "items": ["2、==通过第三方软件下载安装（360）==", "打开360 软件（软件管家），进行搜索需要安装的软件，搜索到之后点“安装”"], "title": "", "ordered": false}, {"h": 462, "t": "img", "w": 808, "id": "s5-1-2-b6", "imp": "normal", "src": "/kb-assets/skill/p123_r0_342190bd36f4b907.png", "title": ""}, {"t": "list", "id": "s5-1-2-b7", "imp": "core", "items": ["3、==通过微软应用商店下载安装（软件数量有限，一般很少使用这种方法安装）==", "==（1）系统的“搜索框”内输入应用商店，点击“Microsoft Store”==", "==（2）找到（可以搜索）安装的应用程序，下载安装。=="], "title": "", "ordered": false}, {"h": 497, "t": "img", "w": 1171, "id": "s5-1-2-b8", "imp": "normal", "src": "/kb-assets/skill/p123_r1_2810b34a68dde42f.png", "title": ""}, {"t": "list", "id": "s5-1-2-b9", "imp": "core", "items": ["4、==软件自带的更新检查或提示==", "==（1）软件（应用）的更新或升级是，软件或应用修复了问题或增加了新功能，为了更好的体验和使用，即有时候需要将软件或应用升级一下。==", "==（2）有些软件会有检查升级功能或软件更新提示，按提示点击更新（下载安装等）=="], "title": "", "ordered": false}, {"h": 330, "t": "img", "w": 979, "id": "s5-1-2-b10", "imp": "normal", "src": "/kb-assets/skill/p123_r2_6399b06cd6d6bef3.png", "title": ""}, {"t": "list", "id": "s5-1-2-b11", "imp": "core", "items": ["5、==微软应用商店的应用更新：用于更新从微软应用商店里下载安装的软件==", "==（1）打开微软应用商店==", "==（2）点击下载图标或者更多图标中的“下载和更新”==", "==（3）找到需要更新的软件，进行更新=="], "title": "", "ordered": false}, {"h": 630, "t": "img", "w": 967, "id": "s5-1-2-b12", "imp": "normal", "src": "/kb-assets/skill/p124_r0_93e79dbcc7ca2193.png", "title": ""}, {"t": "list", "id": "s5-1-2-b13", "imp": "core", "items": ["6、==自行软件官网或其他网站下载最新安装（覆盖）==", "有些软件可以手动去官网或其他网站下载最新版，进行覆盖安装，更新成想要的版本"], "title": "", "ordered": false}, {"h": 609, "t": "img", "w": 769, "id": "s5-1-2-b14", "imp": "normal", "src": "/kb-assets/skill/p124_r1_8cca5bb1881b1212.png", "title": ""}, {"t": "list", "id": "s5-1-2-b15", "imp": "core", "items": ["7、==第三方软件上进行更新（360）==", "有些软件是通过360 安装或360 可以检测到已安装的软件的版本系统，可以通过它来更新软件。"], "title": "", "ordered": false}, {"h": 432, "t": "img", "w": 722, "id": "s5-1-2-b16", "imp": "normal", "src": "/kb-assets/skill/p124_r2_6e85cc8728cffb02.png", "title": ""}, {"t": "list", "id": "s5-1-2-b17", "imp": "core", "items": ["8、==使用windows 10 操作系统自带安全更新功能修复漏洞修复（系统更新）==", "==(1)搜索框中输入Windows 更新设置。=="], "title": "", "ordered": false}, {"h": 519, "t": "img", "w": 632, "id": "s5-1-2-b18", "imp": "normal", "src": "/kb-assets/skill/p125_r0_3ba0726eeca1bb1d.png", "title": ""}, {"t": "list", "id": "s5-1-2-b19", "imp": "core", "items": ["==(2)打开Windows 更新设置=="], "title": "", "ordered": false}, {"h": 520, "t": "img", "w": 654, "id": "s5-1-2-b20", "imp": "normal", "src": "/kb-assets/skill/p125_r1_3b49919d0cc580c6.png", "title": ""}, {"t": "list", "id": "s5-1-2-b21", "imp": "core", "items": ["==(3)点击检查更新。检查是否有需要修复的漏洞。并下载一些补丁包或软件。=="], "title": "", "ordered": false}, {"h": 556, "t": "img", "w": 701, "id": "s5-1-2-b22", "imp": "normal", "src": "/kb-assets/skill/p125_r2_ff82d475c81b6bb1.png", "title": ""}, {"t": "list", "id": "s5-1-2-b23", "imp": "core", "items": ["==12、卸载内置或微软应用商店下载的软件或应用的卸载是指将已安装的应用程序从本台计算机系统中将其删除，包括在安装程序时的Program Files 文件夹复制的程序文件，以及在注册表中写入的程序的相关信息。==", "==Windows 10 并未提供卸载内置应用或商店下载安装的应用的窗口或界面操作。==", "==只能通过 PowerShell 命令来完成。==", "==（1）右击开始菜单==", "==（2）单击PowerShell（管理员）==", "==（3）输入Get-AppxPackage 命令，获取全部信息。==", "==（4）输入 Remove-AppxPackage 应用全名进行删除软件。=="], "title": "", "ordered": false}, {"h": 525, "t": "img", "w": 1350, "id": "s5-1-2-b24", "imp": "normal", "src": "/kb-assets/skill/p126_r0_6e0f97c1ea8b78bc.png", "title": ""}, {"t": "list", "id": "s5-1-2-b25", "imp": "core", "items": ["==13、卸载用户安装的应用程序（应用和功能窗口）=="], "title": "", "ordered": false}, {"h": 666, "t": "img", "w": 1350, "id": "s5-1-2-b26", "imp": "normal", "src": "/kb-assets/skill/p126_r1_5669223ab80ee6e4.png", "title": ""}, {"t": "list", "id": "s5-1-2-b27", "imp": "core", "items": ["9、==卸载用户安装的应用程序（程序和功能）==", "==通过“控制面板”或者“应用和功能”菜单找到“程序和功能”，点击打开“程序和功能”窗口，可以使用弹出来的界面上搜索功能或者鼠标滚动找到自己要卸载的软件。=="], "title": "", "ordered": false}, {"h": 659, "t": "img", "w": 1350, "id": "s5-1-2-b28", "imp": "normal", "src": "/kb-assets/skill/p127_r0_def666e40641c39e.png", "title": ""}, {"t": "list", "id": "s5-1-2-b29", "imp": "core", "items": ["10、==卸载用户安装的应用程序（360）=="], "title": "", "ordered": false}, {"h": 689, "t": "img", "w": 1217, "id": "s5-1-2-b30", "imp": "normal", "src": "/kb-assets/skill/p127_r1_dd58beb713ba598f.png", "title": ""}, {"t": "list", "id": "s5-1-2-b31", "imp": "core", "items": ["2．Windows 10 操作系统下用户帐户管理", "11、==文件夹与路径==：", "（1）==文件夹 - 便于管理文件==。", "- ==文件夹按树形结构组织和存放文件==。", "- ==文件夹树的最高层称为根文件夹==，用“\\”表示。", "- ==一个逻辑磁盘驱动器只有一个根文件夹==。", "- ==在根文件夹中建立的文件夹称为子文件夹==，子文件夹中还可以再包含子文件夹。", "- ==除根文件夹外==，所有文件夹都必须有文件夹名；文件夹的命名规则与文件类似，但一般不需要扩展名。", "（2）==路径==", "① ^^路径^^：==在文件夹的树形结构中==，从根文件夹开始到任何一个文件都有唯一一条通路，该通路上全部结点组成路径，即用“\\”隔开的一组文件夹名及文件名。", "② ^^当前文件夹^^：==正在操作的文件所在的文件夹==。", "12、==任务栏位置的改变==：==任务栏的位置是可以改变的==，通过拖动任务栏可以将它移动到桌面四个边缘的任一位置。【2011】", "13、==磁盘清理==：==“磁盘清理”程序可以将磁盘中无用的文件删除==，以留出更多空间保存需要保存的文件或安装新程序，同时还可以删除一些不再指向应用程序的快捷方式。 操作步骤：", "（1）==单击【开始】按钮==，选择“所有程序”→“附件”→“系统工具”→“磁盘清理”命令，打开“选择驱动器”对话框。", "（2）==在对话框中选择要清理的磁盘驱动器==，单击【确定】按钮。", "（3）==“磁盘清理”程序首先对系统进行分析==，然后在“磁盘清理”对话框中显示报告。", "（4）==如果要删除某个类别中的文件==，选定该类别前的复选框，单击【确定】按钮，在弹出的警告对话框中单击【是】按钮，即可删除选中类别的文件。", "14、==菜单项的显示约定==：==在 Windows 菜单中==，若菜单选项字符呈灰色，表示该选项当前不能执行；带省略号表示会弹出对话框；带黑色三角表示有子菜单；字符为黑色表示可以操作。【2006、2008、2013】", "15、==搜索文件与通配符==：==按 Windows+F 或 F3 打开搜索窗口==。 可以利用文件名、文件中的内容以及大小和修改时间来搜索文件或文件夹。 可以使用通配符“*”和“?”帮助搜索：“*”表示任意多个字符，“?”表示有且仅有一个字符。", "16、^^任务栏的作用^^：^^任务栏显示所有已打开的程序^^，通过任务栏上的按钮可以实现窗口之间的切换。"], "title": "", "ordered": false}, {"t": "callout", "id": "s5-1-2-b32", "imp": "core", "kind": "tip", "text": "Windows 软件形态包括安装版（修改注册表、写入 AppData 与 System32、注册系统服务）与绿色免安装版（解压即用不修改注册表）；规范卸载路径：==Windows 设置 → 应用 → 安装的应用（或控制面板‘程序和功能’），找到目标软件点击‘卸载’执行其专用的 uninst.exe 反安装程序==。", "title": "考向复习提示：软件的安装、升级、绿色便携版与彻底卸载"}, {"t": "callout", "id": "s5-1-2-b33", "imp": "core", "kind": "trap", "text": "专转本极高频常识题：“想卸载已安装的软件，直接在桌面上把该软件的图标按 Delete 键删除即可。”——该判断题==严重错误==！快捷方式仅仅是一个指向主程序的 `.lnk` 链接指针文件；直接删除图标根本没有删除任何软件本体；即使强行删除文件夹，注册表残余和开机自启系统服务依然存在，导致系统报错！", "title": "高频易错陷阱：直接删除桌面快捷方式或 Program Files 文件夹绝不是卸载！"}]$p0b_313$::jsonb, '', $p0s_313$1、软件=程序+数据+相关文档。
2、软件（应用程序）对应有32 位或64 位之分。
3、在32 位和64 位操作系统中安装应用程序时存在的区别
1、安装应用程序的实际过程通常并不复杂，而且大多数应用程序都通过安装向导将其安装到系统中。以下通用流程：
（1）启动安装用户程序：安装文件的名称通常为“Setup.exe”或“Install.exe”
（2）运行程序安装向导：运行安装向导之前，会检测安装程序所需的用户权限。一般需要管理员访权限，可能会需要同意安装协议等才能继续进行安装。
（3）选择安装方式：默认安装和自定义安装。
（4）完成安装：按向导指引操作后，最终完成安装。有些程序安装之后需要重启计算机。
2、通过第三方软件下载安装（360）
打开360 软件（软件管家），进行搜索需要安装的软件，搜索到之后点“安装”
3、通过微软应用商店下载安装（软件数量有限，一般很少使用这种方法安装）
（1）系统的“搜索框”内输入应用商店，点击“Microsoft Store”
（2）找到（可以搜索）安装的应用程序，下载安装。
4、软件自带的更新检查或提示
（1）软件（应用）的更新或升级是，软件或应用修复了问题或增加了新功能，为了更好的体验和使用，即有时候需要将软件或应用升级一下。
（2）有些软件会有检查升级功能或软件更新提示，按提示点击更新（下载安装等）
5、微软应用商店的应用更新：用于更新从微软应用商店里下载安装的软件
（1）打开微软应用商店
（2）点击下载图标或者更多图标中的“下载和更新”
（3）找到需要更新的软件，进行更新
6、自行软件官网或其他网站下载最新安装（覆盖）
有些软件可以手动去官网或其他网站下载最新版，进行覆盖安装，更新成想要的版本
7、第三方软件上进行更新（360）
有些软件是通过360 安装或360 可以检测到已安装的软件的版本系统，可以通过它来更新软件。
8、使用windows 10 操作系统自带安全更新功能修复漏洞修复（系统更新）
(1)搜索框中输入Windows 更新设置。
(2)打开Windows 更新设置
(3)点击检查更新。检查是否有需要修复的漏洞。并下载一些补丁包或软件。
12、卸载内置或微软应用商店下载的软件或应用的卸载是指将已安装的应用程序从本台计算机系统中将其删除，包括在安装程序时的Program Files 文件夹复制的程序文件，以及在注册表中写入的程序的相关信息。
Windows 10 并未提供卸载内置应用或商店下载安装的应用的窗口或界面操作。
只能通过 PowerShell 命令来完成。
（1）右击开始菜单
（2）单击PowerShell（管理员）
（3）输入Get-AppxPackage 命令，获取全部信息。
（4）输入 Remove-AppxPackage 应用全名进行删除软件。
13、卸载用户安装的应用程序（应用和功能窗口）
9、卸载用户安装的应用程序（程序和功能）
通过“控制面板”或者“应用和功能”菜单找到“程序和功能”，点击打开“程序和功能”窗口，可以使用弹出来的界面上搜索功能或者鼠标滚动找到自己要卸载的软件。
10、卸载用户安装的应用程序（360）
2．Windows 10 操作系统下用户帐户管理
11、文件夹与路径：
（1）文件夹 - 便于管理文件。
- 文件夹按树形结构组织和存放文件。
- 文件夹树的最高层称为根文件夹，用“\”表示。
- 一个逻辑磁盘驱动器只有一个根文件夹。
- 在根文件夹中建立的文件夹称为子文件夹，子文件夹中还可以再包含子文件夹。
- 除根文件夹外，所有文件夹都必须有文件夹名；文件夹的命名规则与文件类似，但一般不需要扩展名。
（2）路径
① 路径：在文件夹的树形结构中，从根文件夹开始到任何一个文件都有唯一一条通路，该通路上全部结点组成路径，即用“\”隔开的一组文件夹名及文件名。
② 当前文件夹：正在操作的文件所在的文件夹。
12、任务栏位置的改变：任务栏的位置是可以改变的，通过拖动任务栏可以将它移动到桌面四个边缘的任一位置。【2011】
13、磁盘清理：“磁盘清理”程序可以将磁盘中无用的文件删除，以留出更多空间保存需要保存的文件或安装新程序，同时还可以删除一些不再指向应用程序的快捷方式。 操作步骤：
（1）单击【开始】按钮，选择“所有程序”→“附件”→“系统工具”→“磁盘清理”命令，打开“选择驱动器”对话框。
（2）在对话框中选择要清理的磁盘驱动器，单击【确定】按钮。
（3）“磁盘清理”程序首先对系统进行分析，然后在“磁盘清理”对话框中显示报告。
（4）如果要删除某个类别中的文件，选定该类别前的复选框，单击【确定】按钮，在弹出的警告对话框中单击【是】按钮，即可删除选中类别的文件。
14、菜单项的显示约定：在 Windows 菜单中，若菜单选项字符呈灰色，表示该选项当前不能执行；带省略号表示会弹出对话框；带黑色三角表示有子菜单；字符为黑色表示可以操作。【2006、2008、2013】
15、搜索文件与通配符：按 Windows+F 或 F3 打开搜索窗口。 可以利用文件名、文件中的内容以及大小和修改时间来搜索文件或文件夹。 可以使用通配符“*”和“?”帮助搜索：“*”表示任意多个字符，“?”表示有且仅有一个字符。
16、任务栏的作用：任务栏显示所有已打开的程序，通过任务栏上的按钮可以实现窗口之间的切换。
考向复习提示：软件的安装、升级、绿色便携版与彻底卸载
Windows 软件形态包括安装版（修改注册表、写入 AppData 与 System32、注册系统服务）与绿色免安装版（解压即用不修改注册表）；规范卸载路径：Windows 设置 → 应用 → 安装的应用（或控制面板‘程序和功能’），找到目标软件点击‘卸载’执行其专用的 uninst.exe 反安装程序。
高频易错陷阱：直接删除桌面快捷方式或 Program Files 文件夹绝不是卸载！
专转本极高频常识题：“想卸载已安装的软件，直接在桌面上把该软件的图标按 Delete 键删除即可。”——该判断题严重错误！快捷方式仅仅是一个指向主程序的 .lnk 链接指针文件；直接删除图标根本没有删除任何软件本体；即使强行删除文件夹，注册表残余和开机自启系统服务依然存在，导致系统报错！$p0s_313$, $p0r_313${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S5-1.2 软件的安装、升级、卸载管理。", "题库补充：文件夹与路径 (32题)", "题库补充：任务栏位置的改变 (26题)", "题库补充：磁盘清理 (15题)", "题库补充：菜单项的显示约定 (13题)", "题库补充：搜索文件与通配符 (10题)", "题库补充：任务栏的作用 (9题)", "p0_refine_20261113"], "pages": [122, 123, 124, 125, 126, 127], "spans": 64}$p0r_313$::jsonb, NOW());
