  VALUES (321, 3, $p0b_321$[{"t": "list", "id": "s5-4-1-b1", "imp": "core", "items": ["1、==IP 地址、DNS 服务器的配置==", "==（1）控制面板或Windows 设置界面打开“网络和Internet”设置==", "==（2）单击左侧“以太网”或“WLAN”==", "==（3）单击右侧“更改适配器选项”==", "==（4）打开如下图，进行操作配置IPV4 和IPV6。==", "2、==子网掩码运算、驱动程序文件与 Linux 根目录==：210.33.5.68 与子网掩码 255.255.255.128 按位与运算，得到网络地址 210.33.5.0。 Windows 10 中安装的驱动程序可能包括==多种类型的文件==，如 .sys、.dll、.inf、.exe 及其他类型的文件；安装成功后，可在“设备管理器”中右击该设备，在快捷菜单中选择“属性”查看。"], "title": "", "ordered": false}, {"h": 538, "t": "img", "w": 1350, "id": "s5-4-1-b2", "imp": "normal", "src": "/kb-assets/skill/p140_r0_0832bfd61573800d.png", "title": ""}, {"t": "callout", "id": "s5-4-1-b3", "imp": "core", "kind": "tip", "text": "在网络适配器“Internet 协议版本 4 (TCP/IPv4) 属性”中手动指定静态网络配置，必须完整填写四要素：==1. IP 地址；2. 子网掩码（Subnet Mask）；3. 默认网关（Default Gateway，通常为当前局域网路由器的内网 LAN 口 IP，如 192.168.1.1）；4. 首选 DNS 服务器地址（如 114.114.114.114 或 8.8.8.8）==。", "title": "考向复习提示：Windows 网络参数手动静态配置四要素"}, {"t": "callout", "id": "s5-4-1-b4", "imp": "core", "kind": "trap", "text": "专转本网络排错题绝对经典案例：“电脑能够正常登录 QQ 聊天、玩网游，但是用浏览器输入任何网址都提示无法打开网页报错。”——故障原因有且仅有一个：==本地计算机的“DNS 域名解析服务器配置错误或 DNS 服务器宕机”==！QQ 是直接使用内置固定 IP 协议通信无需解析域名，而网页浏览器必须依赖 DNS 解析网址！", "title": "高频易错陷阱：能上 QQ/微信但打不开网页的故障定位！"}]$p0b_321$::jsonb, '', $p0s_321$1、IP 地址、DNS 服务器的配置
（1）控制面板或Windows 设置界面打开“网络和Internet”设置
（2）单击左侧“以太网”或“WLAN”
（3）单击右侧“更改适配器选项”
（4）打开如下图，进行操作配置IPV4 和IPV6。
2、子网掩码运算、驱动程序文件与 Linux 根目录：210.33.5.68 与子网掩码 255.255.255.128 按位与运算，得到网络地址 210.33.5.0。 Windows 10 中安装的驱动程序可能包括多种类型的文件，如 .sys、.dll、.inf、.exe 及其他类型的文件；安装成功后，可在“设备管理器”中右击该设备，在快捷菜单中选择“属性”查看。
考向复习提示：Windows 网络参数手动静态配置四要素
在网络适配器“Internet 协议版本 4 (TCP/IPv4) 属性”中手动指定静态网络配置，必须完整填写四要素：1. IP 地址；2. 子网掩码（Subnet Mask）；3. 默认网关（Default Gateway，通常为当前局域网路由器的内网 LAN 口 IP，如 192.168.1.1）；4. 首选 DNS 服务器地址（如 114.114.114.114 或 8.8.8.8）。
高频易错陷阱：能上 QQ/微信但打不开网页的故障定位！
专转本网络排错题绝对经典案例：“电脑能够正常登录 QQ 聊天、玩网游，但是用浏览器输入任何网址都提示无法打开网页报错。”——故障原因有且仅有一个：本地计算机的“DNS 域名解析服务器配置错误或 DNS 服务器宕机”！QQ 是直接使用内置固定 IP 协议通信无需解析域名，而网页浏览器必须依赖 DNS 解析网址！$p0s_321$, $p0r_321${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S5-4.1 IP 地址、DNS 服务器的配置。", "题库补充：子网掩码运算、驱动程序文件与 Linux 根目录 (40题)", "p0_refine_20261113"], "pages": [139, 140], "spans": 9}$p0r_321$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 3, updated_at = NOW() WHERE node_id = 321;
END $$;

